/**
 * Pick your world (Sprint 5, founder GO 2026-09-13): the kid's chosen theme.
 * The class sits on documentElement - CelebrationMoment and every theme block
 * in the stylesheets read it from there. Device-local for now; the server
 * record (set-kid-theme, per-kid across devices) is the builder's lane.
 */

export type ThemeId = "clay" | "lantern" | "inkverse" | "chalkboard";

export interface WorldInfo {
  id: ThemeId;
  /** Kid-facing world name (mock Sprint 5 copy). */
  name: string;
}

export const WORLDS: WorldInfo[] = [
  { id: "clay", name: "Clay Room" },
  { id: "lantern", name: "Lantern Trail" },
  { id: "inkverse", name: "Inkverse" },
  { id: "chalkboard", name: "Chalkboard" },
];

/* DS-1 beat 2 worldpick port (mock canon): each world frame previews the
   world's cards on its own sky - two mini cards, the first stamped won. The
   same pair in every world, mirroring the mock's worldpick beat. */
export interface WorldPreviewCard {
  img: string;
  label: string;
  won: boolean;
}
export const WORLD_PREVIEWS: WorldPreviewCard[] = [
  { img: "v1-retell-funny-moment.jpg", label: "Tell a funny thing", won: true },
  { img: "v0-order-own-your-own-snack.jpg", label: "Order your own snack", won: false },
];

/* DS-1 beat 2 pass 3 (mock canon, mock.js ~line 649-652): each world frame
   previews the world's own artifact - clay/inkverse/chalkboard show a slab
   pair (retell stamped won + snack ghost), Lantern Trail shows a lantern
   pair (same two cards). The cards are identical across worlds; only the
   artifact kind changes. */
export type WorldPreviewKind = "slab" | "lantern";
export const WORLD_PREVIEW_KIND: Record<ThemeId, WorldPreviewKind> = {
  clay: "slab",
  lantern: "lantern",
  inkverse: "slab",
  chalkboard: "slab",
};

const STORAGE_KEY = "nila-theme-v1";
const IDS: ThemeId[] = ["clay", "lantern", "inkverse", "chalkboard"];

export function readTheme(): ThemeId {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    return IDS.includes(raw as ThemeId) ? (raw as ThemeId) : "clay";
  } catch {
    return "clay";
  }
}

export function writeTheme(id: ThemeId): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, id);
  } catch {
    /* private mode: the class still applies for the session */
  }
}

export function applyTheme(id: ThemeId): void {
  document.documentElement.classList.remove(...IDS.map((t) => `theme-${t}`));
  document.documentElement.classList.add(`theme-${id}`);
}

export function worldName(id: ThemeId): string {
  return WORLDS.find((w) => w.id === id)?.name ?? "Clay Room";
}
