/**
 * Video activity media payload (video spec v1.1 C1 + PM amendment 2026-09-24).
 * The payload lives NAMESPACED in the existing activities.content jsonb column
 * as content.media - zero migration, no new column. No theme, sizing, or
 * presentation fields in content; the runtime owns all presentation.
 *
 * The picker shape (founder requirement, Sep 23): the parent pastes 1-6
 * YouTube links per video activity; the kid browses real thumbnails and picks
 * with D-pad or touch.
 */

import { canonicalizeYouTubeInput, isYouTubeId } from "./canonicalize.ts";

export type MediaKind = "youtube" | "file";

export interface YouTubeMediaItem {
  /** Canonical bare 11-char YouTube video ID (C2). */
  video_id: string;
  /** Admission-validated duration, seconds. The 90% gate measures against this. */
  duration_s: number;
}

export interface FileMediaItem {
  url: string;
  mime: "video/mp4" | "video/webm";
  duration_s: number;
  bytes: number;
  width: number;
  height: number;
}

export interface ActivityMedia {
  v: 1;
  kind: MediaKind;
  /** 1-6 items (founder's picker rule). */
  items: (YouTubeMediaItem | FileMediaItem)[];
  /** Accessible text track (C8). Required on file route without captions_url. */
  transcript?: string;
  captions_url?: string;
}

export const MEDIA_ITEMS_MIN = 1;
export const MEDIA_ITEMS_MAX = 6;

export type MediaValidation = { ok: true; media: ActivityMedia } | { ok: false; reason: string };

/**
 * Validate and normalize a parent-editor submission into content.media.
 * Typed refusals; an invalid payload is never stored (C2/C8/D3 admission).
 */
export function buildYouTubeMedia(
  inputs: readonly string[],
  durationsS: readonly number[],
  transcript?: string,
): MediaValidation {
  if (inputs.length < MEDIA_ITEMS_MIN || inputs.length > MEDIA_ITEMS_MAX) {
    return { ok: false, reason: `items-count-${inputs.length}-outside-1-6` };
  }
  if (inputs.length !== durationsS.length) {
    return { ok: false, reason: "durations-count-mismatch" };
  }
  const items: YouTubeMediaItem[] = [];
  for (let i = 0; i < inputs.length; i++) {
    const c = canonicalizeYouTubeInput(inputs[i]!);
    if (!c.ok) return { ok: false, reason: `item-${i}-${c.reason}` };
    const d = durationsS[i]!;
    if (!Number.isFinite(d) || d <= 0 || d > 15 * 60) {
      return { ok: false, reason: `item-${i}-bad-duration` };
    }
    items.push({ video_id: c.videoId, duration_s: Math.round(d) });
  }
  const media: ActivityMedia = { v: 1, kind: "youtube", items };
  if (transcript && transcript.trim().length > 0) media.transcript = transcript.trim();
  return { ok: true, media };
}

/** Type guard for a stored content.media payload (client-side render gate). */
export function readActivityMedia(content: unknown): ActivityMedia | null {
  if (typeof content !== "object" || content === null) return null;
  const media = (content as Record<string, unknown>).media;
  if (typeof media !== "object" || media === null) return null;
  const m = media as Record<string, unknown>;
  if (m.v !== 1) return null;
  if (m.kind !== "youtube" && m.kind !== "file") return null;
  if (
    !Array.isArray(m.items) ||
    m.items.length < MEDIA_ITEMS_MIN ||
    m.items.length > MEDIA_ITEMS_MAX
  ) {
    return null;
  }
  if (m.kind === "youtube") {
    for (const item of m.items) {
      const it = item as Record<string, unknown>;
      if (typeof it.video_id !== "string" || !isYouTubeId(it.video_id)) return null;
      if (typeof it.duration_s !== "number" || !(it.duration_s > 0)) return null;
    }
  }
  return media as ActivityMedia;
}
