/**
 * VideoCardPlayer (spec v1.1 sections 3-4): one player surface hosting both
 * media routes. Our UI owns every control - play/pause, our rendered seek
 * bar, volume/mute, captions toggle (YouTube route), exit - D-pad traversable
 * with visible focus and accessible names; the embed's own chrome is never
 * reachable (Y3). Done enables ONLY from the 90% legit-played latch (C7/O3):
 * no open, partial-play, or seek path pays.
 *
 * Route doctrine: YouTube auto-starts zero-press (Y1); a blocked autoplay
 * settles into the branded press-OK-to-play poster, never a spinner (Y2).
 * Direct file starts only on one deliberate kid action (D1). Every failure -
 * unavailable, private, age-restricted, embedding-disabled, network, DNS,
 * API timeout, 404, decode, stall - renders the same honest kid-legible
 * bubble (D4/Y7) with bounded retries (max 3 silent), never a black
 * rectangle or a retry storm. Offline: poster + title, not completable.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { Focusable } from "../focus/FocusRoot";
import {
  mountYouTubePlayer,
  YT_STATE,
  type YTPlayerLike,
  type YouTubeUnavailable,
} from "./youtube-player";
import { DEFAULT_MEDIA_ALLOWLIST } from "../../../../packages/domain/src/video/allowlist.ts";
import type {
  ActivityMedia,
  FileMediaItem,
  YouTubeMediaItem,
} from "../../../../packages/domain/src/video/media.ts";
import { useVideoProgress } from "./useVideoProgress";

const ERROR_COPY = "This video isn't working right now. Try again later.";
const OFFLINE_COPY = "No internet right now. This video can play when you're back online.";
const MAX_SILENT_RETRIES = 3;
const AUTOPLAY_FALLBACK_MS = 2500;

export type PlayerPhase =
  | "loading"
  | "autoplay-blocked" // Y2 branded press-OK-to-play poster
  | "ready" // file route: poster up, waiting for the one deliberate action (D1)
  | "playing"
  | "paused"
  | "ended"
  | "error"
  | "offline";

function formatClock(totalS: number): string {
  const s = Math.max(0, Math.round(totalS));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

export function VideoCardPlayer({
  kidId,
  cardId,
  media,
  itemIndex,
  onDone,
  onExit,
}: {
  kidId: string;
  cardId: string;
  media: ActivityMedia;
  itemIndex: number;
  /** Fires ONLY from the Done control, which renders enabled only at the latch. */
  onDone: () => void;
  onExit: () => void;
}) {
  const item = media.items[itemIndex];
  const durationS = item?.duration_s ?? 0;
  const progress = useVideoProgress(kidId, cardId, durationS);
  const [phase, setPhase] = useState<PlayerPhase>(() => {
    if (typeof navigator !== "undefined" && !navigator.onLine) return "offline";
    // D1: the direct route waits on the poster for one deliberate action;
    // the YouTube route loads toward its zero-press auto-start (Y1).
    return media.kind === "youtube" ? "loading" : "ready";
  });
  const [positionS, setPositionS] = useState(0);
  const [muted, setMuted] = useState(false);
  const [errorKind, setErrorKind] = useState<string | null>(null);
  const hostRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const ytRef = useRef<YTPlayerLike | null>(null);
  const retries = useRef(0);
  const resumed = useRef(false);

  const isYouTube = media.kind === "youtube";

  // --- YouTube route mount (Y1 auto-start; Y2 deterministic fallback) ---
  useEffect(() => {
    if (!isYouTube || !item || !hostRef.current) return;
    let cancelled = false;
    let fallbackTimer = 0;
    mountYouTubePlayer(hostRef.current, {
      videoId: (item as YouTubeMediaItem).video_id,
      origin: window.location.origin,
      captionsPreferred: true,
      onReady: () => {
        if (cancelled) return;
        // Y2: if PLAYING doesn't arrive promptly, the platform blocked the
        // unmuted auto-start - settle into the branded poster, one press plays.
        fallbackTimer = window.setTimeout(() => {
          if (!cancelled) setPhase((p) => (p === "loading" ? "autoplay-blocked" : p));
        }, AUTOPLAY_FALLBACK_MS);
      },
      onStateChange: (state) => {
        if (cancelled) return;
        if (state === YT_STATE.PLAYING) {
          window.clearTimeout(fallbackTimer);
          setPhase("playing");
          // Y6: resume at the last legitimately played point, once per mount.
          if (!resumed.current && progress.resumeS > 0 && ytRef.current) {
            resumed.current = true;
            ytRef.current.seekTo(progress.resumeS, true);
          }
        } else if (state === YT_STATE.PAUSED) {
          setPhase((p) => (p === "playing" ? "paused" : p));
        } else if (state === YT_STATE.ENDED) {
          setPhase("ended");
        }
      },
      onError: (reason: YouTubeUnavailable) => {
        if (cancelled) return;
        setErrorKind(reason);
        setPhase("error");
      },
    })
      .then((player) => {
        if (cancelled) {
          player.destroy();
          return;
        }
        ytRef.current = player;
      })
      .catch((e: Error) => {
        if (cancelled) return;
        setErrorKind(e.message);
        setPhase("error");
      });
    return () => {
      cancelled = true;
      window.clearTimeout(fallbackTimer);
      ytRef.current?.destroy();
      ytRef.current = null;
    };
  }, [isYouTube, cardId, itemIndex]);

  // --- Progress sampler: 500ms wall cadence while playing (Y5/D7) ---
  useEffect(() => {
    if (phase !== "playing") return;
    const tick = () => {
      if (isYouTube && ytRef.current) {
        const pos = ytRef.current.getCurrentTime();
        setPositionS(pos);
        progress.sample(pos, ytRef.current.getPlayerState() === YT_STATE.PLAYING, 1);
      } else if (!isYouTube && videoRef.current) {
        const v = videoRef.current;
        setPositionS(v.currentTime);
        progress.sample(v.currentTime, !v.paused && !v.ended, v.playbackRate);
      }
    };
    const id = window.setInterval(tick, 500);
    return () => window.clearInterval(id);
  }, [phase, isYouTube]);

  // --- File route guards (D2: allowlist re-checked at play time, fail closed) ---
  const fileItem = !isYouTube ? (item as FileMediaItem | undefined) : undefined;
  const fileUrlOk = fileItem ? DEFAULT_MEDIA_ALLOWLIST(fileItem.url).ok : false;

  const togglePlay = useCallback(() => {
    if (isYouTube && ytRef.current) {
      const st = ytRef.current.getPlayerState();
      if (st === YT_STATE.PLAYING) ytRef.current.pauseVideo();
      else ytRef.current.playVideo();
    } else if (videoRef.current) {
      const v = videoRef.current;
      if (v.paused || v.ended) void v.play();
      else v.pause();
    }
  }, [isYouTube]);

  const toggleMute = useCallback(() => {
    if (isYouTube && ytRef.current) {
      if (ytRef.current.isMuted()) {
        ytRef.current.unMute();
        setMuted(false);
      } else {
        ytRef.current.mute();
        setMuted(true);
      }
    } else if (videoRef.current) {
      videoRef.current.muted = !videoRef.current.muted;
      setMuted(videoRef.current.muted);
    }
  }, [isYouTube]);

  const seekBy = useCallback(
    (delta: number) => {
      // Seek jumps never count toward the threshold (D7/Y5); the domain
      // accumulator rejects them. Resume is likewise unaffected.
      if (isYouTube && ytRef.current) {
        ytRef.current.seekTo(Math.max(0, ytRef.current.getCurrentTime() + delta), true);
      } else if (videoRef.current) {
        videoRef.current.currentTime = Math.max(0, videoRef.current.currentTime + delta);
      }
    },
    [isYouTube],
  );

  if (!item) {
    return (
      <div className="nila-video-bubble" role="alert">
        {ERROR_COPY}
      </div>
    );
  }

  if (phase === "offline") {
    return (
      <div className="nila-video-stage nila-video-offline">
        <div className="nila-video-bubble" role="status">
          {OFFLINE_COPY}
        </div>
        <Focusable id="video-exit" className="nila-action nila-secondary" autoFocus onOk={onExit}>
          Back
        </Focusable>
      </div>
    );
  }

  if (phase === "error") {
    return (
      <div className="nila-video-stage nila-video-error" data-error-kind={errorKind ?? "unknown"}>
        <div className="nila-video-bubble" role="alert">
          {ERROR_COPY}
        </div>
        <Focusable id="video-exit" className="nila-action nila-secondary" autoFocus onOk={onExit}>
          Back
        </Focusable>
      </div>
    );
  }

  const playedFraction = progress.durationS > 0 ? progress.acceptedS / progress.durationS : 0;

  return (
    <div className={`nila-video-stage nila-video-${phase}`}>
      {/* Player surface. The YouTube iframe mounts focus-inert inside the
          host; the file route renders a controlled <video> (no autoplay, D1). */}
      <div className="nila-video-host" ref={hostRef}>
        {!isYouTube && fileUrlOk && (
          <video
            ref={videoRef}
            src={fileItem!.url}
            preload="metadata"
            playsInline
            tabIndex={-1}
            aria-hidden="true"
            onPlay={() => setPhase("playing")}
            onPause={() => setPhase((p) => (p === "playing" ? "paused" : p))}
            onEnded={() => setPhase("ended")}
            onError={() => {
              // D4: bounded silent retries, then the honest bubble.
              if (retries.current < MAX_SILENT_RETRIES && videoRef.current) {
                retries.current += 1;
                videoRef.current.load();
              } else {
                setErrorKind("decode-or-network");
                setPhase("error");
              }
            }}
          />
        )}
        {!isYouTube && !fileUrlOk && (
          <div className="nila-video-bubble" role="alert">
            {ERROR_COPY}
          </div>
        )}
      </div>

      {phase === "loading" && (
        <div className="nila-video-overlay nila-video-loading">
          <span className="nila-pulse">Getting your video...</span>
        </div>
      )}

      {(phase === "autoplay-blocked" || (phase === "ready" && !isYouTube)) && (
        <div className="nila-video-overlay nila-video-poster">
          <Focusable
            id="video-play"
            className="nila-action nila-primary"
            autoFocus
            onOk={togglePlay}
          >
            Play
          </Focusable>
        </div>
      )}

      {/* Our control surface (D6/Y3). Every control D-pad traversable,
          >=48dp, accessibly named. Playback never navigates out of the card. */}
      <div className="nila-video-controls" role="group" aria-label="Video controls">
        {phase !== "autoplay-blocked" && phase !== "ready" && (
          <>
            <Focusable id="video-toggle" className="nila-video-ctl" autoFocus onOk={togglePlay}>
              {phase === "playing" ? "Pause" : "Play"}
            </Focusable>
            <Focusable id="video-back-10" className="nila-video-ctl" onOk={() => seekBy(-10)}>
              -10s
            </Focusable>
            <Focusable id="video-fwd-10" className="nila-video-ctl" onOk={() => seekBy(10)}>
              +10s
            </Focusable>
            <Focusable id="video-mute" className="nila-video-ctl" onOk={toggleMute}>
              {muted ? "Unmute" : "Mute"}
            </Focusable>
          </>
        )}
        {/* Our rendered progress: legit-played toward the 90% gate, plus the
            elapsed/remaining clock for 7+ bands (D6). */}
        <div
          className="nila-video-progressbar"
          role="progressbar"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(playedFraction * 100)}
          aria-label="Watched"
        >
          <div className="nila-video-progressfill" style={{ width: `${playedFraction * 100}%` }} />
        </div>
        <span className="nila-video-clock">
          {formatClock(positionS)} / {formatClock(progress.durationS)}
        </span>
        {/* C7/O3 pay gate: Done exists only once the 90% legit-played latch
            has fired. A bare player "ended" event (e.g. after a seek jump,
            which the accumulator rejected) never surfaces it. */}
        {progress.unlocked ? (
          <Focusable id="video-done" className="nila-action nila-primary" onOk={onDone}>
            Done
          </Focusable>
        ) : null}
        <Focusable id="video-exit" className="nila-action nila-secondary" onOk={onExit}>
          Back
        </Focusable>
      </div>
    </div>
  );
}
