/**
 * Timer overlay focus session (plan 51861fbc s3.3-3.4, PM design ruling
 * Option C 2026-09-25). A generation-token machine: every open() mints a new
 * token; stale tokens (a close racing a re-open, an async storage result
 * landing after close) fail isCurrent() and are ignored. No boolean
 * "restore pending" flag and no id-prefix origin capture: the origin is the
 * exact screen identity + focus id recorded at open.
 *
 * Restore on close: the origin focus id, only if the SAME screen is still
 * showing and the id is still registered+focusable; otherwise one bounded
 * attempt at FALLBACK_FOCUS_ID; otherwise nothing (FocusRoot's own unmount
 * fallback already holds a valid focus). The fallback utility is never
 * recorded as "content focus", so it can't become an origin.
 */

export const FALLBACK_FOCUS_ID = "timer-utility";

export interface FocusSessionHost {
  /** Current focused id (SpatialNav truth). */
  focused(): string | null;
  /** Programmatic focus; false when the id isn't registered/focusable. */
  focus(id: string): boolean;
}

export interface FocusSessionToken {
  readonly generation: number;
}

export interface FocusSessionOrigin {
  readonly screen: string;
  readonly focusId: string | null;
}

export type RestoreOutcome = "origin" | "fallback" | "none" | "stale";

/** Content focus = anything the kid navigated to on the page; the utility is not content. */
export function shouldRecordContentFocus(id: string | null): id is string {
  return id !== null && id !== FALLBACK_FOCUS_ID;
}

export interface FocusSessionMachine {
  open(screen: string): FocusSessionToken;
  isCurrent(token: FocusSessionToken): boolean;
  isOpen(): boolean;
  origin(): FocusSessionOrigin | null;
  /** Record the last content focus seen while no session is open. */
  noteContentFocus(id: string | null): void;
  setMembership(ids: Iterable<string>): void;
  isMember(id: string): boolean;
  close(token: FocusSessionToken, currentScreen: string): RestoreOutcome;
}

export function createFocusSessionMachine(host: FocusSessionHost): FocusSessionMachine {
  let generation = 0;
  let openGeneration: number | null = null;
  let origin: FocusSessionOrigin | null = null;
  let lastContentFocus: string | null = null;
  let membership: ReadonlySet<string> = new Set();

  return {
    open(screen) {
      generation += 1;
      const f = host.focused();
      const focusId = shouldRecordContentFocus(f) ? f : lastContentFocus;
      origin = Object.freeze({ screen, focusId });
      openGeneration = generation;
      membership = new Set();
      return Object.freeze({ generation });
    },
    isCurrent(token) {
      return openGeneration !== null && token.generation === openGeneration;
    },
    isOpen() {
      return openGeneration !== null;
    },
    origin() {
      return origin;
    },
    noteContentFocus(id) {
      if (openGeneration !== null) return;
      if (shouldRecordContentFocus(id)) lastContentFocus = id;
    },
    setMembership(ids) {
      membership = new Set(ids);
    },
    isMember(id) {
      return membership.has(id);
    },
    close(token, currentScreen) {
      if (openGeneration === null || token.generation !== openGeneration) return "stale";
      const o = origin;
      openGeneration = null;
      origin = null;
      membership = new Set();
      if (o && o.screen === currentScreen && o.focusId !== null && host.focus(o.focusId))
        return "origin";
      if (host.focus(FALLBACK_FOCUS_ID)) return "fallback";
      return "none";
    },
  };
}

/**
 * Overlay membership, structural: every [data-focus-id] whose closest
 * [data-timer-state] ancestor is the overlay root. A fresh snapshot per
 * keypress; an empty result is returned as-is (scoped move fails closed).
 */
export function overlayFocusableIds(root: ParentNode | null): string[] {
  if (!root) return [];
  const out: string[] = [];
  root.querySelectorAll<HTMLElement>("[data-focus-id]").forEach((el) => {
    if (!el.closest("[data-timer-state]")) return;
    const id = el.getAttribute("data-focus-id");
    if (id) out.push(id);
  });
  return out;
}
