/**
 * Nila timer - pure domain (spec v3-r, "Architecture": this file owns state,
 * reducer, bounds, validation and clock reconciliation; no DOM, no storage).
 *
 * One communal, install-local, kid-controlled countdown: 3 / 10 / 15 minutes.
 * The durable record is key `active-v1`; this module validates and
 * canonicalizes it, and reconciles it against clocks. UI and IndexedDB live
 * elsewhere and never do timer math.
 */

export const TIMER_RECORD_VERSION = 1 as const;
export const TIMER_RECORD_KEY = "active-v1" as const;

export const TIMER_PRESETS_MS = [180_000, 600_000, 900_000] as const;
export type TimerPresetMs = (typeof TIMER_PRESETS_MS)[number];

export type TimerStatus = "running" | "paused" | "finished";
export type TimerPresentation = "racer" | "numerals";

/** Exactly the fields of the spec's durable record, nothing else. */
export interface TimerRecord {
  version: typeof TIMER_RECORD_VERSION;
  timerId: string;
  presetMs: TimerPresetMs;
  status: TimerStatus;
  /** Wall ms when this timer was first started (never changes on pause/resume). */
  startedWallMs: number;
  /** Wall deadline while running; null while paused or finished. */
  deadlineWallMs: number | null;
  /** Remaining ms at the last anchor (start/resume/pause); 0 when finished. */
  remainingMs: number;
  /** Wall ms the timer finished; null unless finished. */
  finishedWallMs: number | null;
  /** True once the kid dismissed the finish. Only meaningful when finished. */
  acknowledged: boolean;
  presentation: TimerPresentation;
  /** Monotonic write counter; every persisted transition increments it. */
  revision: number;
}

export const TIMER_RECORD_FIELDS = [
  "version",
  "timerId",
  "presetMs",
  "status",
  "startedWallMs",
  "deadlineWallMs",
  "remainingMs",
  "finishedWallMs",
  "acknowledged",
  "presentation",
  "revision",
] as const satisfies readonly (keyof TimerRecord)[];

/** Largest wall time we accept (year ~2286); rejects absurd / overflowing values. */
export const MAX_SAFE_WALL_MS = 10_000_000_000_000;

export type TimerValidationError =
  | "not-object"
  | "bad-version"
  | "bad-timer-id"
  | "bad-preset"
  | "bad-status"
  | "bad-started"
  | "bad-deadline"
  | "bad-remaining"
  | "bad-finished"
  | "bad-acknowledged"
  | "bad-presentation"
  | "bad-revision"
  | "status-invariant";

export type TimerValidation =
  { ok: true; record: TimerRecord } | { ok: false; error: TimerValidationError };

export const isPreset = (v: unknown): v is TimerPresetMs =>
  typeof v === "number" && (TIMER_PRESETS_MS as readonly number[]).includes(v);

const isSafeTime = (v: unknown): v is number =>
  typeof v === "number" &&
  Number.isFinite(v) &&
  Number.isInteger(v) &&
  v >= 0 &&
  v <= MAX_SAFE_WALL_MS;

const isTimerId = (v: unknown): v is string =>
  typeof v === "string" && v.length >= 1 && v.length <= 64 && /^[A-Za-z0-9_-]+$/.test(v);

/**
 * Validate an unknown value as a durable timer record and canonicalize it:
 * unknown fields are dropped; nothing is coerced. Any doubt -> error, so a
 * corrupt record surfaces the recovery state rather than a wrong timer.
 */
export function validateTimerRecord(input: unknown): TimerValidation {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    return { ok: false, error: "not-object" };
  }
  const r = input as Record<string, unknown>;
  if (r.version !== TIMER_RECORD_VERSION) return { ok: false, error: "bad-version" };
  if (!isTimerId(r.timerId)) return { ok: false, error: "bad-timer-id" };
  if (!isPreset(r.presetMs)) return { ok: false, error: "bad-preset" };
  if (r.status !== "running" && r.status !== "paused" && r.status !== "finished") {
    return { ok: false, error: "bad-status" };
  }
  if (!isSafeTime(r.startedWallMs)) return { ok: false, error: "bad-started" };
  if (r.deadlineWallMs !== null && !isSafeTime(r.deadlineWallMs)) {
    return { ok: false, error: "bad-deadline" };
  }
  if (!isSafeTime(r.remainingMs) || r.remainingMs > r.presetMs) {
    return { ok: false, error: "bad-remaining" };
  }
  if (r.finishedWallMs !== null && !isSafeTime(r.finishedWallMs)) {
    return { ok: false, error: "bad-finished" };
  }
  if (typeof r.acknowledged !== "boolean") return { ok: false, error: "bad-acknowledged" };
  if (r.presentation !== "racer" && r.presentation !== "numerals") {
    return { ok: false, error: "bad-presentation" };
  }
  if (!isSafeTime(r.revision) || (r.revision as number) < 1) {
    return { ok: false, error: "bad-revision" };
  }
  const record: TimerRecord = {
    version: TIMER_RECORD_VERSION,
    timerId: r.timerId,
    presetMs: r.presetMs,
    status: r.status,
    startedWallMs: r.startedWallMs,
    deadlineWallMs: r.deadlineWallMs as number | null,
    remainingMs: r.remainingMs,
    finishedWallMs: r.finishedWallMs as number | null,
    acknowledged: r.acknowledged,
    presentation: r.presentation,
    revision: r.revision as number,
  };
  if (!statusInvariantHolds(record)) return { ok: false, error: "status-invariant" };
  return { ok: true, record };
}

function statusInvariantHolds(r: TimerRecord): boolean {
  switch (r.status) {
    case "running":
      return (
        r.deadlineWallMs !== null &&
        r.remainingMs > 0 &&
        r.finishedWallMs === null &&
        !r.acknowledged &&
        r.deadlineWallMs >= r.startedWallMs
      );
    case "paused":
      return (
        r.deadlineWallMs === null &&
        r.remainingMs > 0 &&
        r.finishedWallMs === null &&
        !r.acknowledged
      );
    case "finished":
      return r.deadlineWallMs === null && r.remainingMs === 0 && r.finishedWallMs !== null;
  }
}

/** Canonical form for storage and readback comparison (field order fixed). */
export function canonicalizeTimerRecord(r: TimerRecord): TimerRecord {
  const v = validateTimerRecord(r);
  if (!v.ok) throw new TimerDomainError(`cannot canonicalize invalid record: ${v.error}`);
  return v.record;
}

/** Every canonical field equal (the spec's readback comparison). */
export function timerRecordsEqual(a: TimerRecord, b: TimerRecord): boolean {
  return TIMER_RECORD_FIELDS.every((f) => Object.is(a[f], b[f]));
}

export class TimerDomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "TimerDomainError";
  }
}

// ---------------------------------------------------------------------------
// Transitions on the durable record. All pure; the caller persists the result.
// ---------------------------------------------------------------------------

const safeNow = (nowWallMs: number): number => {
  if (!isSafeTime(Math.round(nowWallMs)) || !Number.isFinite(nowWallMs)) {
    throw new TimerDomainError("wall clock sample is not a safe finite time");
  }
  return Math.round(nowWallMs);
};

export function startTimer(args: {
  timerId: string;
  presetMs: number;
  nowWallMs: number;
  presentation: TimerPresentation;
  previousRevision?: number;
}): TimerRecord {
  if (!isPreset(args.presetMs)) throw new TimerDomainError("preset must be 3, 10 or 15 minutes");
  if (!isTimerId(args.timerId)) throw new TimerDomainError("bad timer id");
  const now = safeNow(args.nowWallMs);
  return canonicalizeTimerRecord({
    version: TIMER_RECORD_VERSION,
    timerId: args.timerId,
    presetMs: args.presetMs,
    status: "running",
    startedWallMs: now,
    deadlineWallMs: now + args.presetMs,
    remainingMs: args.presetMs,
    finishedWallMs: null,
    acknowledged: false,
    presentation: args.presentation,
    revision: (args.previousRevision ?? 0) + 1,
  });
}

/**
 * Replace = one atomic record swap with a NEW timer id (no empty gap). The
 * revision continues from the replaced record so readback can't confuse them.
 */
export function replaceTimer(
  current: TimerRecord,
  args: { timerId: string; presetMs: number; nowWallMs: number },
): TimerRecord {
  if (args.timerId === current.timerId) throw new TimerDomainError("replace needs a new timer id");
  return startTimer({
    timerId: args.timerId,
    presetMs: args.presetMs,
    nowWallMs: args.nowWallMs,
    presentation: current.presentation,
    previousRevision: current.revision,
  });
}

/** Pause from a running record; `remainingMs` comes from the live monotonic clock. */
export function pauseTimer(current: TimerRecord, remainingMs: number): TimerRecord {
  if (current.status !== "running") throw new TimerDomainError("only a running timer pauses");
  const remaining = clampRemaining(remainingMs, current.presetMs);
  if (remaining <= 0) throw new TimerDomainError("timer already reached zero; finish instead");
  return canonicalizeTimerRecord({
    ...current,
    status: "paused",
    deadlineWallMs: null,
    remainingMs: remaining,
    revision: current.revision + 1,
  });
}

export function resumeTimer(current: TimerRecord, nowWallMs: number): TimerRecord {
  if (current.status !== "paused") throw new TimerDomainError("only a paused timer resumes");
  const now = safeNow(nowWallMs);
  return canonicalizeTimerRecord({
    ...current,
    status: "running",
    // A backwards wall jump before startedWallMs must not break the invariant.
    startedWallMs: Math.min(current.startedWallMs, now),
    deadlineWallMs: now + current.remainingMs,
    revision: current.revision + 1,
  });
}

export function finishTimer(current: TimerRecord, finishedWallMs: number): TimerRecord {
  if (current.status === "finished") return current;
  const at = safeNow(finishedWallMs);
  return canonicalizeTimerRecord({
    ...current,
    status: "finished",
    deadlineWallMs: null,
    remainingMs: 0,
    finishedWallMs: at,
    acknowledged: false,
    revision: current.revision + 1,
  });
}

export function acknowledgeTimer(current: TimerRecord): TimerRecord {
  if (current.status !== "finished")
    throw new TimerDomainError("only a finished timer is acknowledged");
  if (current.acknowledged) return current;
  return canonicalizeTimerRecord({
    ...current,
    acknowledged: true,
    revision: current.revision + 1,
  });
}

export function setPresentation(
  current: TimerRecord,
  presentation: TimerPresentation,
): TimerRecord {
  if (current.presentation === presentation) return current;
  return canonicalizeTimerRecord({ ...current, presentation, revision: current.revision + 1 });
}

// ---------------------------------------------------------------------------
// Clock reconciliation.
// ---------------------------------------------------------------------------

export function clampRemaining(ms: number, presetMs: number): number {
  if (!Number.isFinite(ms)) return 0;
  return Math.min(presetMs, Math.max(0, Math.round(ms)));
}

export type ReconcileResult =
  | { kind: "running"; record: TimerRecord; remainingMs: number }
  | { kind: "paused"; record: TimerRecord; remainingMs: number }
  | { kind: "finished"; record: TimerRecord; changed: boolean };

/**
 * Reload reconciliation: remaining = deadline - Date.now(), clamped to
 * [0, preset]; <= 0 finishes. A backward wall jump can never push remaining
 * above the preset. Non-finite wall samples leave the record untouched and
 * report the anchored remaining (fail safe: never extend, never finish early).
 */
export function reconcileOnLoad(record: TimerRecord, nowWallMs: number): ReconcileResult {
  if (record.status === "finished") return { kind: "finished", record, changed: false };
  if (record.status === "paused")
    return { kind: "paused", record, remainingMs: record.remainingMs };
  const deadline = record.deadlineWallMs as number;
  if (!Number.isFinite(nowWallMs)) {
    return { kind: "running", record, remainingMs: record.remainingMs };
  }
  const remaining = clampRemaining(deadline - nowWallMs, record.presetMs);
  if (remaining <= 0) {
    return { kind: "finished", record: finishTimer(record, deadline), changed: true };
  }
  return { kind: "running", record, remainingMs: remaining };
}

/**
 * In-process clock: a performance.now() anchor. Wall-clock jumps never bend
 * it. Non-finite or decreasing samples (performance reset, bad WebView) are
 * treated as "no time passed" and re-anchor at the new sample, so remaining
 * never increases and never jumps.
 */
export class MonotonicCountdown {
  private anchorMono: number;
  private anchorRemaining: number;
  private lastMono: number;
  private lastRemaining: number;

  constructor(
    remainingMs: number,
    nowMono: number,
    private readonly presetMs: TimerPresetMs,
  ) {
    const r = clampRemaining(remainingMs, presetMs);
    const m = Number.isFinite(nowMono) ? nowMono : 0;
    this.anchorMono = m;
    this.anchorRemaining = r;
    this.lastMono = m;
    this.lastRemaining = r;
  }

  /** Remaining ms at this monotonic sample; monotonically non-increasing. */
  remaining(nowMono: number): number {
    if (!Number.isFinite(nowMono) || nowMono < this.lastMono) {
      // Re-anchor with no progress credited.
      if (Number.isFinite(nowMono)) {
        this.anchorMono = nowMono;
        this.anchorRemaining = this.lastRemaining;
        this.lastMono = nowMono;
      }
      return this.lastRemaining;
    }
    const r = clampRemaining(this.anchorRemaining - (nowMono - this.anchorMono), this.presetMs);
    this.lastMono = nowMono;
    this.lastRemaining = Math.min(this.lastRemaining, r);
    return this.lastRemaining;
  }

  /**
   * Page came back from hidden. Some platforms stop performance.now() during
   * device sleep; if the wall clock advanced more than the monotonic clock
   * while hidden, that gap is sleep and is credited. Never adds time back.
   */
  resumeFromHidden(args: {
    hiddenMono: number;
    hiddenWall: number;
    nowMono: number;
    nowWall: number;
  }): number {
    const current = this.remaining(args.nowMono);
    const wallGap = args.nowWall - args.hiddenWall;
    const monoGap = args.nowMono - args.hiddenMono;
    if (![wallGap, monoGap].every(Number.isFinite) || wallGap <= 0 || monoGap < 0) return current;
    const sleep = wallGap - monoGap;
    if (sleep <= SLEEP_TOLERANCE_MS) return current;
    const next = clampRemaining(current - sleep, this.presetMs);
    this.anchorMono = args.nowMono;
    this.anchorRemaining = next;
    this.lastMono = args.nowMono;
    this.lastRemaining = next;
    return next;
  }
}

export const SLEEP_TOLERANCE_MS = 1_500;

// ---------------------------------------------------------------------------
// Presentation helpers.
// ---------------------------------------------------------------------------

/** Ages 4-6 racer-first, 7+ numerals-first, unknown/unreliable racer (+ exact time always shown). */
export function defaultPresentation(age: number | null | undefined): TimerPresentation {
  if (typeof age !== "number" || !Number.isFinite(age) || age < 4) return "racer";
  return age >= 7 ? "numerals" : "racer";
}

/** Final quarter: 0 < remaining <= preset / 4 (warm coral + "Almost there"). */
export function isFinalQuarter(remainingMs: number, presetMs: TimerPresetMs): boolean {
  return remainingMs > 0 && remainingMs <= presetMs / 4;
}

/** Exact M:SS, ceiling seconds so 0:00 appears only at the true finish. */
export function formatMSS(remainingMs: number): string {
  const total = Math.max(0, Math.ceil((Number.isFinite(remainingMs) ? remainingMs : 0) / 1000));
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${s.toString().padStart(2, "0")}`;
}

/** Racer progress 0..1 along the track. Reduced motion steps it in 1/20 increments. */
export function racerProgress(
  remainingMs: number,
  presetMs: TimerPresetMs,
  reducedMotion = false,
): number {
  const p = 1 - clampRemaining(remainingMs, presetMs) / presetMs;
  return reducedMotion ? Math.floor(p * 20) / 20 : p;
}

export type TimerAnnouncement = "start" | "pause" | "resume" | "1m" | "10s" | "finish";

/** Tick announcements only on crossing 1:00 and 0:10 - never every second. */
export function tickAnnouncement(
  prevRemainingMs: number,
  remainingMs: number,
): TimerAnnouncement | null {
  if (!(remainingMs < prevRemainingMs)) return null;
  if (prevRemainingMs > 60_000 && remainingMs <= 60_000 && remainingMs > 10_000) return "1m";
  if (prevRemainingMs > 10_000 && remainingMs <= 10_000 && remainingMs > 0) return "10s";
  return null;
}

export function newTimerId(
  random: () => number = Math.random,
  nowWallMs: number = Date.now(),
): string {
  const r = Math.floor(random() * 2 ** 32)
    .toString(36)
    .padStart(7, "0");
  return `t${Math.max(0, Math.floor(nowWallMs)).toString(36)}${r}`;
}

// ---------------------------------------------------------------------------
// View state machine (overlay). Pure; storage outcomes are fed in as events.
// ---------------------------------------------------------------------------

export type TimerView =
  | "idle"
  | "pick"
  | "running"
  | "final-quarter"
  | "paused"
  | "stop-confirm"
  | "replace-confirm"
  | "finished"
  | "recovery"
  | "erase-confirm"
  | "storage-unavailable";

export const TIMER_VIEWS: readonly TimerView[] = [
  "idle",
  "pick",
  "running",
  "final-quarter",
  "paused",
  "stop-confirm",
  "replace-confirm",
  "finished",
  "recovery",
  "erase-confirm",
  "storage-unavailable",
];

export interface TimerViewState {
  view: TimerView;
  /** Overlay shown over the current screen. */
  open: boolean;
  record: TimerRecord | null;
}

export type TimerEvent =
  | { type: "open" }
  | { type: "close" }
  | { type: "back" }
  | { type: "loaded"; record: TimerRecord | null; remainingMs?: number }
  | { type: "load-corrupt" }
  | { type: "choose-preset" }
  | { type: "persisted"; record: TimerRecord | null }
  | { type: "persist-failed" }
  | { type: "tick"; remainingMs: number }
  | { type: "request-stop" }
  | { type: "request-replace" }
  | { type: "request-erase" }
  | { type: "cancel" };

export const initialTimerViewState: TimerViewState = { view: "idle", open: false, record: null };

function viewForRecord(record: TimerRecord | null, remainingMs?: number): TimerView {
  if (!record) return "idle";
  if (record.status === "finished") return record.acknowledged ? "idle" : "finished";
  if (record.status === "paused") return "paused";
  const r = remainingMs ?? record.remainingMs;
  return isFinalQuarter(r, record.presetMs) ? "final-quarter" : "running";
}

/**
 * The overlay's view reducer. Back NEVER cancels a timer: it steps out of a
 * confirm to its parent view, or closes the overlay; the record is untouched.
 */
export function timerViewReducer(state: TimerViewState, event: TimerEvent): TimerViewState {
  switch (event.type) {
    case "loaded": {
      const view = viewForRecord(event.record, event.remainingMs);
      return {
        ...state,
        record:
          event.record && view === "idle" && event.record.status === "finished"
            ? null
            : event.record,
        view,
      };
    }
    case "load-corrupt":
      return { ...state, record: null, view: "recovery" };
    case "open": {
      if (state.view === "recovery" || state.view === "storage-unavailable")
        return { ...state, open: true };
      const base = viewForRecord(state.record);
      return { ...state, open: true, view: base === "idle" ? "pick" : base };
    }
    case "close":
      return { ...state, open: false, view: parentView(state) };
    case "back": {
      switch (state.view) {
        case "stop-confirm":
        case "replace-confirm":
          return { ...state, view: viewForRecord(state.record) };
        case "erase-confirm":
          return { ...state, view: "recovery" };
        case "storage-unavailable":
          return {
            ...state,
            view: viewForRecord(state.record) === "idle" ? "pick" : viewForRecord(state.record),
          };
        case "recovery":
          // Back from recovery is the initial (nothing started) state.
          return { ...state, open: false, view: "idle", record: null };
        case "finished":
          // Back does not acknowledge; closing keeps the finish visible next open.
          return { ...state, open: false };
        default:
          return { ...state, open: false, view: parentView(state) };
      }
    }
    case "choose-preset":
      return state;
    case "persisted": {
      const view = viewForRecord(event.record);
      if (event.record && event.record.status === "finished" && event.record.acknowledged) {
        return { ...state, record: null, view: "idle", open: false };
      }
      if (!event.record) {
        return { ...state, record: null, view: state.open ? "pick" : "idle" };
      }
      return { ...state, record: event.record, view };
    }
    case "persist-failed":
      return { ...state, view: "storage-unavailable", open: true };
    case "tick": {
      if (!state.record || state.record.status !== "running") return state;
      if (state.view !== "running" && state.view !== "final-quarter") return state;
      return {
        ...state,
        view: isFinalQuarter(event.remainingMs, state.record.presetMs)
          ? "final-quarter"
          : "running",
      };
    }
    case "request-stop":
      if (!state.record || state.record.status === "finished") return state;
      return { ...state, view: "stop-confirm" };
    case "request-replace":
      if (!state.record || state.record.status === "finished") return state;
      return { ...state, view: "replace-confirm" };
    case "request-erase":
      if (state.view !== "recovery") return state;
      return { ...state, view: "erase-confirm" };
    case "cancel":
      if (state.view === "erase-confirm") return { ...state, view: "recovery" };
      if (state.view === "stop-confirm" || state.view === "replace-confirm") {
        return { ...state, view: viewForRecord(state.record) };
      }
      return state;
  }
}

function parentView(state: TimerViewState): TimerView {
  const v = viewForRecord(state.record);
  return v;
}

/** Utility-target label: timer icon when idle, else active M:SS or "Paused". */
export function utilityLabel(
  record: TimerRecord | null,
  remainingMs: number,
): { kind: "icon" } | { kind: "time"; text: string } | { kind: "paused" } | { kind: "done" } {
  if (!record) return { kind: "icon" };
  if (record.status === "paused") return { kind: "paused" };
  if (record.status === "finished")
    return record.acknowledged ? { kind: "icon" } : { kind: "done" };
  return { kind: "time", text: formatMSS(remainingMs) };
}
