import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createApi, onQueueRefused } from "./api/client";
import { telemetry } from "./api/telemetry";
import {
  clearFamilyKey,
  keyForKid,
  saveFamilyId,
  saveFamilyKey,
  storedFamilyKey,
} from "./api/family-key";
import { Focusable, FocusRoot } from "./focus/FocusRoot";
import { ScreenView } from "./screens/Screens";
import { TimerHost } from "./screens/timer/TimerHost";
import {
  nextScreen,
  WEEK_CLEAR_REWARD,
  type KidEvent,
  type ScreenDefinition,
} from "./state/screens";
import {
  drawConcept,
  readLastConcept,
  writeLastConcept,
  type CelebrationConceptId,
} from "./state/celebration-draw";
import { applyTheme, readTheme, writeTheme, worldName } from "./state/theme";
import {
  applyCharacter,
  readCharacter,
  CHARACTER_PACKS,
  type CharacterId,
} from "./state/characters";
import {
  allCardsDone,
  clearAllDonePending,
  markAllDonePending,
  takeAllDonePending,
} from "./state/all-done";
import { shotFixture } from "./state/shot-fixtures";
import {
  deviceWelcomed,
  markDeviceWelcomed,
  markProfileWelcomed,
  profileWelcomed,
  shouldSkipFirstProfileWelcome,
} from "./state/welcome-flags";
import type { ThemeId } from "./state/theme";
import { DEMO_KID_ID } from "./state/demo";

declare const __APP_BUILD__: string;

// Runtime pairing (2026-09-14): the grown-up "Pair this TV" entry appears on
// the picker only while the device holds no household binding - no build-time
// family id (the APK rides the public bundle) and no paired key in storage.
const needsPairEntry = () =>
  !(import.meta.env?.VITE_NILA_FAMILY_ID as string | undefined) && !storedFamilyKey();

// L1 closure (2026-09-13): the offline fallback bundles the DEMO KID ONLY -
// the real pilot kids' production UUIDs no longer ship in the public bundle.
// The live picker is server-driven (get-kids?family=...); this list only
// covers cold-start/offline.
const DEMO_KIDS: { id: string; name: string; avatarImage: string | null }[] = [
  {
    id: "00000000-0000-4000-8000-000000000002",
    name: "Demo Kid",
    avatarImage: "/assets/characters/faces/demo-kid.png",
  },
];

// Per-critic demo profiles (critic work order 2026-09-13, finding 5):
// parallel critics sharing one mutable demo profile contaminate each other
// (a concurrent completion read as a ghost wallet jump; a pre-completed quiz
// card blocked quiz-flow grading). The two extra profiles exist server-side
// in the demo family with their own clean shelves; they join the picker ONLY
// behind ?demo-critics=1 so the founder's production picker never shows them.
const CRITIC_DEMO_KIDS: { id: string; name: string; avatarImage: string | null }[] = [
  {
    id: "00000000-0000-4000-8000-000000000013",
    name: "Vihaan (demo)",
    avatarImage: "/assets/characters/faces/demo-kid.png",
  },
  {
    id: "00000000-0000-4000-8000-000000000014",
    name: "Inaaya (demo)",
    avatarImage: "/assets/characters/faces/demo-kid.png",
  },
];
// DS-1 port shot mode (PM ruling, backlog 32): ?shot=<beat>&theme=<world>
// renders a deterministic fixture screen for the visual-diff gate, with no
// API calls and no reducers. Inert without the param; never the loop.
const SHOT_PARAMS =
  typeof window !== "undefined" ? new URLSearchParams(window.location.search) : null;
const SHOT_CARDS_RAW = SHOT_PARAMS?.get("cards");
const SHOT_CARDS =
  SHOT_CARDS_RAW && /^\d+$/.test(SHOT_CARDS_RAW)
    ? Math.max(1, Math.min(20, parseInt(SHOT_CARDS_RAW, 10)))
    : null;
const SHOT_SCREEN = SHOT_PARAMS?.get("shot")
  ? shotFixture(SHOT_PARAMS.get("shot")!, SHOT_CARDS)
  : null;
const SHOT_THEME_RAW = SHOT_PARAMS?.get("theme");
const SHOT_THEME =
  SHOT_SCREEN &&
  SHOT_THEME_RAW &&
  (["clay", "lantern", "inkverse", "chalkboard"] as ThemeId[]).includes(SHOT_THEME_RAW as ThemeId)
    ? (SHOT_THEME_RAW as ThemeId)
    : null;
if (SHOT_THEME) {
  applyTheme(SHOT_THEME);
}
// Character pack override, shot mode only (mirrors ?theme=): ?character=
// <pack-id> selects the pack for the cell; inert without the shot param.
// Elephant default; Zig only when explicitly selected (PM, backlog 166).
const SHOT_CHARACTER_RAW = SHOT_PARAMS?.get("character");
if (SHOT_SCREEN && SHOT_CHARACTER_RAW && CHARACTER_PACKS.some((p) => p.id === SHOT_CHARACTER_RAW)) {
  applyCharacter(SHOT_CHARACTER_RAW as CharacterId);
}

// Port-gate measurement aid: ?shot=<beat>&mark=<css-selector> outlines the
// matching element in magenta so its true-viewport bbox is pixel-locatable.
// Shot-mode only; inert in the product.
const SHOT_MARK = SHOT_PARAMS?.get("mark");
/* Shot mode freezes scroll: the focus system scrolls an overflowing screen
   to the focused control (product-correct - the focused action must stay
   visible on TVs/phones), but the port gate measures canonical layout
   against an unscrolled mock snapshot. overflow: clip makes the screen
   unscrollable even programmatically, so shots capture the top-anchored
   canon state. Inert in the product (shot param only). */
if (SHOT_SCREEN) {
  const style = document.createElement("style");
  style.textContent = ".nila-screen { overflow: clip !important; }";
  document.head.appendChild(style);
}
if (SHOT_SCREEN && SHOT_MARK) {
  const style = document.createElement("style");
  style.textContent = `${SHOT_MARK} { outline: 4px solid #ff00ff !important; outline-offset: -2px; }`;
  document.head.appendChild(style);
}

const SHOW_CRITIC_DEMOS =
  typeof window !== "undefined" && new URLSearchParams(window.location.search).has("demo-critics");
// PICKER-fix v1.1 F8 (PM row 308): test-only failure fixture. ?demo-empty
// forces the failed-profile-load state, bypassing stored/bundled profile
// reads; query param only, never linked, unreachable from normal production
// navigation. The failure state never falls through to the Demo Kid seeded
// success state; its retry re-runs the load and re-fails deterministically
// while the param stays.
const DEMO_EMPTY =
  typeof window !== "undefined" && new URLSearchParams(window.location.search).has("demo-empty");
// Under the fixture every face-picker construction carries the forced
// failure flag; the flag only renders when the kids list is empty.
const PICKER_FAILURE = DEMO_EMPTY ? { loadFailed: true as const } : {};
const PICKER_KIDS = SHOW_CRITIC_DEMOS ? [...DEMO_KIDS, ...CRITIC_DEMO_KIDS] : DEMO_KIDS;

type Shelf = Extract<ScreenDefinition, { kind: "shelf" }>;

export default function App() {
  // The device's world applies from the very first paint - a kid who picked
  // Lantern Trail never sees a clay flash. Shot mode keeps its fixture theme:
  // the stored/default theme must not clobber it (gate themes went vacuous).
  useMemo(() => applyTheme(SHOT_THEME ?? readTheme()), []);
  useMemo(() => {
    if (!SHOT_SCREEN) applyCharacter(readCharacter());
  }, []);
  const api = useMemo(() => createApi(), []);
  // ?demo-empty bypasses the bundled identities entirely (F8).
  const [kids, setKids] = useState(DEMO_EMPTY ? [] : PICKER_KIDS);
  // PM welcome routing (2026-09-14, relayed via main): first-open of the
  // install roots at welcome, once; repeat opens land on the face-picker
  // instantly.
  const [screen, setScreen] = useState<ScreenDefinition>(() =>
    DEMO_EMPTY
      ? { kind: "face-picker", kids: [], pairEntry: needsPairEntry(), ...PICKER_FAILURE }
      : deviceWelcomed()
        ? { kind: "face-picker", kids: [], pairEntry: needsPairEntry() }
        : { kind: "welcome" },
  );
  // True while this is the install's first-open session: profiles resolved
  // during it skip their per-profile welcome (no back-to-back intro).
  const firstOpenSession = useRef(!deviceWelcomed());
  // A profile mid first-entry: their welcome shows before their world, then
  // meet-worlds marks them welcomed and returns to the face-picker.
  const pendingWelcomeKid = useRef<string | null>(null);
  const [confirmExit, setConfirmExit] = useState(false);
  const [shelves, setShelves] = useState<Record<string, Shelf>>({});
  // Double-OK on the same card fires no second draw and no second payout
  // (r4 R11; F7 one-press-one-act at the flow level).
  const inFlightMarks = useRef(new Set<string>());

  // What does the real TV actually report? One metric per boot tells us.
  useEffect(() => {
    telemetry("screen-metrics", "boot", {
      detail: {
        vw: window.innerWidth,
        vh: window.innerHeight,
        dpr: window.devicePixelRatio,
        screenW: window.screen.width,
        screenH: window.screen.height,
        build: typeof __APP_BUILD__ === "string" ? __APP_BUILD__ : "unknown",
      },
    });
  }, []);

  // The face picker is server-driven like everything else; the bundled demo
  // kid is only the offline fallback.
  const loadKids = useCallback(() => {
    // Shot mode renders fixtures only: no API calls (the boot fetch would
    // hang the port gate's network-idle wait offline).
    if (SHOT_SCREEN) return;
    // F8 fixture: deterministic failure - no stored-profile read, no
    // bundled-identity fallback, no Demo Kid fallthrough.
    if (DEMO_EMPTY) {
      setKids([]);
      setScreen((current) =>
        current.kind === "face-picker"
          ? { kind: "face-picker", kids: [], pairEntry: needsPairEntry(), ...PICKER_FAILURE }
          : current,
      );
      return;
    }
    void api.getKids().then((fetched) => {
      // Offline/unreachable: the bundled identities are the fallback (their
      // documented role) - they appear ONLY now, never as a flash under the
      // server list.
      const serverList = fetched && fetched.length > 0 ? fetched : null;
      if (serverList === null && PICKER_KIDS.length > 0) {
        setKids(PICKER_KIDS);
        setScreen((current) =>
          current.kind === "face-picker"
            ? { kind: "face-picker", kids: PICKER_KIDS, pairEntry: needsPairEntry() }
            : current,
        );
        return;
      }
      if (serverList && serverList.length > 0) {
        // Critic-demo profiles ride the param even after the server list
        // lands (the picker is server-driven and would overwrite them).
        const list = SHOW_CRITIC_DEMOS
          ? [
              ...serverList,
              ...CRITIC_DEMO_KIDS.filter((c) => !serverList.some((k) => k.id === c.id)),
            ]
          : serverList;
        setKids(list);
        // A late get-kids response must never throw a kid back out of the shelf
        // they already picked from the bundled cold-start identities.
        setScreen((current) =>
          current.kind === "face-picker"
            ? { kind: "face-picker", kids: list, pairEntry: needsPairEntry() }
            : current,
        );
      }
    });
  }, [api]);

  // The face picker is server-driven; retry from the F8 failure state and
  // the boot effect share this one load path.
  useEffect(() => {
    loadKids();
  }, [loadKids]);

  // TRIP-A: a queued completion the server refuses on replay was a ghost -
  // resync that kid to server truth so no pending star stands unbacked.
  useEffect(
    () =>
      onQueueRefused((kidId) => {
        void api
          .getShelf(kidId)
          .then((fresh) => setShelves((prev) => ({ ...prev, [kidId]: fresh })));
      }),
    [api],
  );

  const shelfFor = useCallback(
    (kidId: string): Shelf =>
      shelves[kidId] ?? {
        kind: "shelf",
        kidId,
        kidName: "",
        cards: [],
        wallet: 0,
        weekEarned: 0,
        weekLine: 42,
        streakRun: 0,
        boostActive: false,
      },
    [shelves],
  );

  // P0 pairing fix (2026-09-16): dispatch's deps exclude `screen` by design
  // (R21 undo class), so handlers that must see the CURRENT screen read this
  // ref - on a fresh unpaired device no dep ever changes after boot, and the
  // pair-key-submit guard on the stale closure screen silently swallowed OK.
  const screenRef = useRef(screen);
  screenRef.current = screen;
  const dispatch = useCallback(
    (event: KidEvent) => {
      const currentKidId = "kidId" in screen ? screen.kidId : undefined;
      if (event.type === "undo")
        telemetry("undo", screen.kind, { kidId: currentKidId, cardId: event.cardId });
      if (event.type === "switch-kid") {
        setScreen({ kind: "face-picker", kids, pairEntry: needsPairEntry(), ...PICKER_FAILURE });
        return;
      }
      if (event.type === "meet-worlds") {
        markDeviceWelcomed();
        if (pendingWelcomeKid.current) {
          markProfileWelcomed(pendingWelcomeKid.current);
          pendingWelcomeKid.current = null;
        }
        setScreen({ kind: "face-picker", kids, pairEntry: needsPairEntry(), ...PICKER_FAILURE });
        return;
      }
      // Tenancy stage 3: a non-demo kid with no paired key detours to the
      // pairing screen (demo kids ride the shipped demo key, so the public
      // demo stays world-open - PM ruling 2026-09-14).
      if (event.type === "picked-face" && !keyForKid(event.kidId)) {
        telemetry("pair-required", screen.kind, {});
        setScreen({ kind: "pairing", kidId: event.kidId });
        return;
      }
      // Per-profile first entry (same ruling): a profile created in a later
      // session gets welcome once before its world; repeat entries are
      // instant. Demo profiles are not exempt - a fresh browser's first pick
      // is exactly the hello moment.
      if (event.type === "picked-face" && !profileWelcomed(event.kidId)) {
        // PM decision message 2026-09-21 08:12 IST, P0-1 acceptance; production walkthrough nila-internal@08bf1cb3; observed loop: production walkthrough
        // 2026-09-21: welcome -> picker -> welcome -> picker loop on the demo
        // device): the first profile of the first-open session skips its
        // per-profile welcome and goes straight in; the pairing path already
        // applied this skip at pair time. Profiles 2+ keep their hello.
        if (shouldSkipFirstProfileWelcome(firstOpenSession.current)) {
          markProfileWelcomed(event.kidId);
        } else {
          pendingWelcomeKid.current = event.kidId;
          setScreen({ kind: "welcome" });
          return;
        }
      }
      // Runtime pairing (2026-09-14, founder fix-path): the picker's grown-up
      // entry on an unpaired device - no face picked yet, so kidId is "".
      if (event.type === "open-pairing") {
        setScreen({ kind: "pairing", kidId: "" });
        return;
      }
      // F8: the failure state's retry re-runs the profile load path (under
      // ?demo-empty it re-fails deterministically).
      if (event.type === "retry-kids-load") {
        setScreen({ kind: "face-picker", kids: [], pairEntry: needsPairEntry() });
        loadKids();
        return;
      }
      const curScreen = screenRef.current;
      if (event.type === "pair-key-submit" && curScreen.kind === "pairing") {
        // Validate BEFORE saving: the server resolves the key to a household
        // (x-nila-family-key alone). A saved-but-wrong key was the old stage-3
        // trap - the TV remembered a key that opened nothing.
        const pairingKidId = curScreen.kidId;
        void api.pairResolve(event.key).then((res) => {
          if (res.kind === "ok") {
            saveFamilyKey(event.key);
            saveFamilyId(res.family);
            telemetry("pair-saved", curScreen.kind, {});
            if (pairingKidId === "") {
              const list = SHOW_CRITIC_DEMOS
                ? [
                    ...res.kids,
                    ...CRITIC_DEMO_KIDS.filter((c) => !res.kids.some((k) => k.id === c.id)),
                  ]
                : res.kids;
              setKids(list);
              // Amendment, narrowed by PM decision message 2026-09-21 08:12 IST, P0-1 acceptance; production walkthrough nila-internal@08bf1cb3: only the
              // FIRST profile of the first-open session skips its per-profile
              // welcome (one kid must not get the intro twice back-to-back).
              // Profiles 2+ were added to a list, not greeted - their first
              // pick is their hello moment, not repetition. res.kids[0] is the
              // first household profile (the critic-demo merge rides `list`).
              if (firstOpenSession.current && res.kids[0]) markProfileWelcomed(res.kids[0].id);
              setScreen({ kind: "face-picker", kids: list });
            } else if (!profileWelcomed(pairingKidId)) {
              pendingWelcomeKid.current = pairingKidId;
              setScreen({ kind: "welcome" });
            } else {
              setScreen({ kind: "loading-shelf", kidId: pairingKidId });
            }
            return;
          }
          telemetry("pair-refused", curScreen.kind, {
            detail: { status: res.kind === "refused" ? res.status : 0 },
          });
          setScreen({
            kind: "pairing",
            kidId: pairingKidId,
            error:
              res.kind === "offline"
                ? "No connection - check the TV is online, then try again."
                : "That key did not open a family - check it on the grown-up phone and try again.",
          });
        });
        return;
      }
      if (event.type === "leave" && screen.kind === "pairing") {
        setScreen({ kind: "face-picker", kids, pairEntry: needsPairEntry() });
        return;
      }
      if (event.type === "leave") {
        // Day close: leaving the moment (or the completed card) after the
        // day's final completion lands on "All done for today!" exactly
        // once - the take consumes the arm. Reload-safe because the arm
        // rides storage; next-day reset because any not-all-done shelf
        // truth clears it (see the shelf effect and undo resync).
        const cur = screenRef.current;
        if (
          (cur.kind === "celebration" || cur.kind === "completed-card") &&
          takeAllDonePending(cur.kidId)
        ) {
          setScreen({
            kind: "cleared-shelf",
            kidId: cur.kidId,
            kidName: shelfFor(cur.kidId).kidName,
          });
          return;
        }
      }
      if (event.type === "undo") {
        // R21: the kid takes their own mark back from the screen they're on.
        // Functional read - dispatch's closure `screen` lags one navigation
        // (its deps exclude screen by design). A done card opened straight
        // off the shelf left the closure on "shelf", the guard below failed
        // against the stale screen, and undo no-op'd (critic TRIP 2026-09-13,
        // repro'd by Vihaan + Inaaya on the launch build).
        setScreen((now) => {
          if (now.kind !== "celebration" && now.kind !== "completed-card") return now;
          if (now.card.id !== event.cardId) return now;
          const { kidId, card } = now;
          void api.undoDone(kidId, card.id).then((res) =>
            api.getShelf(kidId).then((fresh) => {
              setShelves((prev) => ({ ...prev, [kidId]: fresh }));
              // The take-back broke the all-done state: a day-close arm
              // from the old truth is stale now.
              if (!allCardsDone(fresh.cards)) clearAllDonePending(kidId);
              // TRIP-1: a refused take-back lands on server truth WITH its
              // honest decline (PM-ratified string) - never silent.
              if (!res.ok && res.refused?.reason === "already-spent") {
                setScreen({
                  ...fresh,
                  undoDeclined: "Those stars already went to the store - ask Amma or Appa.",
                });
              } else {
                setScreen(fresh);
              }
            }),
          );
          return now;
        });
        return;
      }
      if (event.type === "open-worlds") {
        // Functional read, not the closure screen: a fast press on the door
        // the moment the shelf renders must not be eaten (dispatch's deps
        // exclude screen by design).
        setScreen((now) =>
          "kidId" in now
            ? {
                kind: "worldpick",
                kidId: now.kidId,
                kidName: "kidName" in now ? now.kidName : undefined,
                current: readTheme(),
              }
            : now,
        );
        return;
      }
      if (event.type === "picked-world") {
        // Reversible, instant: the whole app reskins now (the theme class is
        // global), the picker stays open so the kid can keep trying worlds.
        // The guard is a functional read - dispatch's closure `screen` lags
        // one navigation (its deps exclude screen by design).
        applyTheme(event.theme);
        writeTheme(event.theme);
        setScreen((now) =>
          now.kind === "worldpick"
            ? { ...now, current: event.theme, pickedName: worldName(event.theme) }
            : now,
        );
        return;
      }
      if (event.type === "opened-store") {
        const kidId = "kidId" in screen ? screen.kidId : null;
        if (kidId) {
          // Beta browse (user-flows v5 decision 11): the listing read is the
          // only store call the app makes - stock and prices are server
          // truth, never bundled guesses. No transaction surface exists.
          void api.getStore(kidId).then((listing) => {
            if (!listing) {
              setScreen({
                kind: "store",
                kidId,
                wallet: shelfFor(kidId).wallet,
                items: [],
                loadFailed: true,
              });
              return;
            }
            setScreen({
              kind: "store",
              kidId,
              wallet: listing.wallet,
              items: listing.items.map((item) => ({
                ...item,
                affordable: item.price <= listing.wallet,
              })),
            });
          });
        }
        return;
      }
      setScreen((current) => {
        // TRIP-6: a replayed quiz never re-commits - its answers are pure play.
        if (
          (event.type === "i-did-it" &&
            (current.kind === "card-detail" || current.kind === "video")) ||
          (event.type === "quiz-answered" && current.kind === "quiz" && !current.replayed)
        ) {
          const kidId = current.kidId;
          const cardId = event.cardId;
          const markKey = `${kidId}:${cardId}`;
          if (inFlightMarks.current.has(markKey)) return current;
          inFlightMarks.current.add(markKey);
          const kidName = shelfFor(kidId).kidName;
          void api
            .markDone(
              kidId,
              cardId,
              event.type === "quiz-answered"
                ? { answerId: event.answerId }
                : event.type === "i-did-it" && event.stepUp
                  ? { stepUp: true }
                  : undefined,
            )
            .then((verdict) => {
              // The server's word lands on the moment: real stars, real goes.
              // TRIP-A: a typed refusal means the tap hit a card that is not
              // active server-side (ghost mark) - never celebrate; resync to
              // server truth and land on the fresh shelf.
              if (verdict.refused) {
                inFlightMarks.current.delete(markKey);
                void api.getShelf(kidId).then((fresh) => {
                  setShelves((prev) => ({ ...prev, [kidId]: fresh }));
                  if (!allCardsDone(fresh.cards)) clearAllDonePending(kidId);
                  setScreen(fresh);
                });
                return;
              }
              // No client completion event: the complete function mirrors it
              // server-side, so offline replays attribute too (2026-09-12).
              const shelfNow = shelfFor(kidId);
              // R16/R17: JACKPOT is deterministic - only the completion that
              // crosses the weekly star line plays it, never a random draw.
              const crossed =
                verdict.done &&
                !verdict.pendingSync &&
                shelfNow.weekEarned < shelfNow.weekLine &&
                shelfNow.weekEarned + verdict.starsEarned >= shelfNow.weekLine;
              // R11: the draw consumes the random source once, at completion
              // time, and the result rides with the completion's screen.
              const excluded = readLastConcept(kidId);
              let concept: "jackpot" | CelebrationConceptId;
              if (crossed) {
                concept = "jackpot";
              } else {
                concept = drawConcept(excluded, Math.random);
                writeLastConcept(kidId, concept);
              }
              const walletAfter = shelfNow.wallet + verdict.starsEarned;
              const cardsLeftToday = shelfNow.cards.filter(
                (c) => !c.done && c.id !== cardId,
              ).length;
              // DS-1 day close (2026-09-21 walkthrough: 5/5 never fired
              // "All done for today!"): the finishing completion arms one
              // day-close fire. A later not-all-done shelf truth (undo,
              // refused replay, fresh day) clears a stale arm, so an
              // offline-pending mark can never fire a false close.
              if (verdict.done && cardsLeftToday === 0) markAllDonePending(kidId);
              setScreen((now) => {
                if (now.kind === "quiz" && now.card.id === cardId) {
                  // Completion-pays: the kid is on the inline reveal. The
                  // moment's payload waits on the beat; quiz-reveal-ack
                  // carries it into the one celebration (beat's close).
                  const moment = {
                    kidName,
                    starsEarned: verdict.starsEarned,
                    done: verdict.done,
                    goesDone: verdict.goesDone,
                    goesRequired: verdict.goesRequired,
                    concept,
                    excluded: crossed ? null : excluded,
                    walletAfter,
                    cardsLeftToday,
                    crossedLine: crossed,
                    lineRewardTitle: crossed ? WEEK_CLEAR_REWARD : undefined,
                    pendingSync: verdict.pendingSync === true,
                  };
                  // I-0042: the verdict closes the quiz beat (the shelf no
                  // longer ships the answer key): a committed wrong answer
                  // reveals inline with the verdict's key; anything else
                  // celebrates directly (PM decision 8 unchanged).
                  if (verdict.wasRight === false) {
                    return {
                      ...now,
                      revealed: true,
                      knownCorrectAnswerId: verdict.correctAnswerId ?? null,
                      pendingMoment: moment,
                    };
                  }
                  return {
                    kind: "celebration" as const,
                    kidId,
                    card: now.card,
                    ...moment,
                  };
                }
                if (now.kind === "celebration" && now.card.id === cardId) {
                  if (verdict.done === false) {
                    // R18: the server says this go only advanced the card -
                    // the mini-ack in place, not the moment.
                    return {
                      kind: "card-detail",
                      kidId,
                      card: {
                        ...now.card,
                        goesDone: verdict.goesDone,
                        goesRequired: verdict.goesRequired,
                      },
                      miniAck: {
                        goesDone: verdict.goesDone ?? 0,
                        goesRequired: verdict.goesRequired ?? 1,
                        at: Date.now(),
                      },
                    };
                  }
                  return {
                    ...now,
                    kidName,
                    starsEarned: verdict.starsEarned,
                    done: verdict.done,
                    goesDone: verdict.goesDone,
                    goesRequired: verdict.goesRequired,
                    concept,
                    excluded: crossed ? null : excluded,
                    walletAfter,
                    cardsLeftToday,
                    crossedLine: crossed,
                    lineRewardTitle: crossed ? WEEK_CLEAR_REWARD : undefined,
                    pendingSync: verdict.pendingSync === true,
                  };
                }
                if (now.kind === "card-detail" && now.card.id === cardId && now.miniAck) {
                  if (verdict.done) {
                    // The optimistic mini-ack was actually the finishing go:
                    // the full moment plays from beat 0 (r4 R18 pin 2).
                    return {
                      kind: "celebration",
                      kidId,
                      kidName,
                      card: now.card,
                      starsEarned: verdict.starsEarned,
                      done: true,
                      goesDone: verdict.goesDone,
                      goesRequired: verdict.goesRequired,
                      concept,
                      excluded: crossed ? null : excluded,
                      walletAfter,
                      cardsLeftToday,
                      crossedLine: crossed,
                      lineRewardTitle: crossed ? WEEK_CLEAR_REWARD : undefined,
                      pendingSync: verdict.pendingSync === true,
                    };
                  }
                  return {
                    ...now,
                    card: {
                      ...now.card,
                      goesDone: verdict.goesDone ?? now.card.goesDone,
                      goesRequired: verdict.goesRequired ?? now.card.goesRequired,
                    },
                    miniAck: {
                      ...now.miniAck,
                      goesDone: verdict.goesDone ?? now.miniAck.goesDone,
                      goesRequired: verdict.goesRequired ?? now.miniAck.goesRequired,
                    },
                  };
                }
                return now;
              });
              void api.getShelf(kidId).then((fresh) => {
                setShelves((prev) => ({ ...prev, [kidId]: fresh }));
              });
            })
            .finally(() => inFlightMarks.current.delete(markKey));
        }
        return nextScreen(current, event, shelfFor);
      });
    },
    [api, shelfFor, kids, loadKids],
  );

  // Fetch (or read the offline cache of) today's shelf when one opens.
  const openShelfKidId =
    screen.kind === "shelf" || screen.kind === "loading-shelf" || screen.kind === "shelf-recovery"
      ? screen.kidId
      : null;
  const shelfAttempt =
    screen.kind === "loading-shelf" || screen.kind === "shelf-recovery" ? (screen.attempt ?? 0) : 0;
  useEffect(() => {
    if (!openShelfKidId) return;
    let cancelled = false;
    const recovery = setTimeout(() => {
      if (!cancelled) {
        setScreen((current) =>
          (current.kind === "loading-shelf" || current.kind === "shelf-recovery") &&
          current.kidId === openShelfKidId
            ? { kind: "shelf-recovery", kidId: openShelfKidId, attempt: shelfAttempt }
            : current,
        );
      }
    }, 15000);
    void api.getShelf(openShelfKidId).then((fresh) => {
      if (!cancelled) {
        if (fresh.pairNeeded) {
          // The server refused at the family gate. A stored key means it was
          // rejected (rotation/typo) - forget it and say so; no stored key
          // means the rollout ended and pairing is now required.
          const hadKey = !!storedFamilyKey();
          if (hadKey) clearFamilyKey();
          setScreen({
            kind: "pairing",
            kidId: openShelfKidId,
            error: hadKey ? "That key did not work. Check it and try again." : undefined,
          });
          return;
        }
        if (fresh.loadFailed) {
          setScreen({ kind: "shelf-recovery", kidId: openShelfKidId, attempt: shelfAttempt });
          return;
        }
        if (fresh.cards.length > 0) setShelves((prev) => ({ ...prev, [openShelfKidId]: fresh }));
        // Day close, server truth: a not-all-done shelf (fresh day, undo,
        // refusal) clears any stale arm - the deterministic next-day
        // reset; an all-done shelf with a live arm fires the close here,
        // which is what makes it survive a reload between the final
        // completion and the moment.
        const dayClosed = allCardsDone(fresh.cards);
        if (!dayClosed) clearAllDonePending(fresh.kidId);
        setScreen((current) => {
          const onShelfPath =
            (current.kind === "loading-shelf" ||
              current.kind === "shelf-recovery" ||
              current.kind === "shelf") &&
            current.kidId === openShelfKidId;
          if (!onShelfPath) return current;
          if (dayClosed && takeAllDonePending(fresh.kidId)) {
            return { kind: "cleared-shelf", kidId: fresh.kidId, kidName: fresh.kidName };
          }
          return fresh;
        });
      }
    });
    return () => {
      cancelled = true;
      clearTimeout(recovery);
    };
  }, [api, openShelfKidId, shelfAttempt]);

  // Android TV delivers Back only to the shell, which re-injects it as a key.
  // Back walks the loop (detail -> shelf); at the shelf or picker it asks
  // before leaving, and only that prompt may close the app (NilaShell.exit).
  const handleBack = () => {
    if (confirmExit) {
      setConfirmExit(false);
      return;
    }
    // K10: Back leaves a demo showing for the face picker - the exit confirm
    // is the kids' flow, never part of a demo.
    if (screen.kind === "shelf" && screen.kidId === DEMO_KID_ID) {
      dispatch({ type: "switch-kid" });
      return;
    }
    const inAppBack =
      "kidId" in screen &&
      screen.kind !== "shelf" &&
      screen.kind !== "loading-shelf" &&
      screen.kind !== "shelf-recovery";
    if (inAppBack)
      dispatch({ type: "leave", focusCardId: "card" in screen ? screen.card.id : undefined });
    else setConfirmExit(true);
  };
  const exitApp = () => {
    setConfirmExit(false);
    (window as unknown as { NilaShell?: { exit?: () => void } }).NilaShell?.exit?.();
  };

  if (SHOT_SCREEN) {
    // Shot mode: fixture only; every hook above already ran harmlessly.
    return (
      <FocusRoot onBack={() => {}}>
        <ScreenView screen={SHOT_SCREEN} dispatch={() => {}} />
      </FocusRoot>
    );
  }

  return (
    <FocusRoot onBack={handleBack}>
      {confirmExit ? (
        <main className="nila-screen">
          <h1 className="nila-title">Leave Nila?</h1>
          <div className="nila-row nila-exit-row">
            <Focusable
              id="exit-stay"
              className="nila-action nila-primary"
              onOk={() => setConfirmExit(false)}
            >
              Stay
            </Focusable>
            <Focusable id="exit-leave" className="nila-action" onOk={exitApp}>
              Leave
            </Focusable>
          </div>
        </main>
      ) : (
        <ScreenView screen={screen} dispatch={dispatch} />
      )}
      {/* Timer utility + overlay (spec v3-r): every production screen and the
          Leave Nila? confirm; never shot fixtures. Remote open is inert while
          Leave Nila? owns keys (PM Option C). */}
      <TimerHost
        screenId={confirmExit ? "leave" : `${screen.kind}:${"kidId" in screen ? screen.kidId : ""}`}
        keyEnabled={!confirmExit}
      />
      <img
        className="nila-mark"
        src={`${import.meta.env.BASE_URL}assets/characters/elephant-stand.png`}
        alt=""
      />
    </FocusRoot>
  );
}
