import React from "react";
import { createRoot } from "react-dom/client";
import App from "./App";
import { HomePreview, homePreviewBootstrap } from "./screens/HomePreview";
import { responsiveImageSet, WELCOME_HERO_SIZES } from "./screens/art";
import { ensureWelcomeHeroPreload } from "./screens/welcome-hero-readiness";
import {
  applyCharacter,
  characterAsset,
  characterBaseWidths,
  readCharacter,
} from "./state/characters";
import "./styles.css";
import "./styles/themes.css";
import "./styles/home-preview.css";
import "./video/video.css";

const homePreviewConfig = homePreviewBootstrap(
  window.location.pathname,
  window.location.search,
  import.meta.env.BASE_URL,
);
const isHomePreview = homePreviewConfig !== null;
if (!isHomePreview) {
  const character = readCharacter();
  applyCharacter(character);
  const hero = responsiveImageSet(
    characterAsset(character, "base"),
    characterBaseWidths(character) ?? [],
  );
  ensureWelcomeHeroPreload(
    document,
    hero.fallbackSrc,
    hero.webpSrcSet || undefined,
    WELCOME_HERO_SIZES,
  );
}
if (homePreviewConfig) document.documentElement.className = `theme-${homePreviewConfig.theme}`;

if (!isHomePreview && "serviceWorker" in navigator) {
  void navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`);
}

createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    {homePreviewConfig ? <HomePreview config={homePreviewConfig} /> : <App />}
  </React.StrictMode>,
);
