/**
 * Sampling bridge between a playing media element/player and the domain
 * 90% legit-played accumulator (spec v1.1 D7/Y5/C7). Samples at 500ms wall
 * cadence (<=1s contract) while the source reports playing, persists the
 * legit resume point per kid+card (Y6), and exposes the Done latch.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import {
  feedSample,
  initProgress,
  resumePosition,
  type ProgressState,
} from "../../../../packages/domain/src/video/progress.ts";
import { readVideoProgress, writeVideoProgress, clearVideoProgress } from "./progress-store";

export interface VideoProgressApi {
  /** The Done latch (C7). The Done control renders enabled only when true. */
  unlocked: boolean;
  /** Accepted seconds so far / needed (for our own rendered progress bar). */
  acceptedS: number;
  durationS: number;
  /** The only legal resume point (Y6). */
  resumeS: number;
  /** Feed one sample from the active source. */
  sample: (positionS: number, playing: boolean, rate?: number) => void;
  /** Reset after the completion mints (replay mints nothing, Y5). */
  reset: () => void;
}

export function useVideoProgress(
  kidId: string,
  cardId: string,
  durationS: number,
): VideoProgressApi {
  const [state, setState] = useState<ProgressState>(() => {
    const stored = readVideoProgress(kidId, cardId);
    const base = initProgress(durationS);
    if (!stored) return base;
    return {
      ...base,
      acceptedS: stored.acceptedS,
      maxAcceptedPositionS: stored.maxAcceptedPositionS,
      unlocked: stored.unlocked,
    };
  });
  const stateRef = useRef(state);
  stateRef.current = state;

  useEffect(() => {
    writeVideoProgress(kidId, cardId, {
      maxAcceptedPositionS: state.maxAcceptedPositionS,
      acceptedS: state.acceptedS,
      unlocked: state.unlocked,
    });
  }, [kidId, cardId, state]);

  const sample = useCallback((positionS: number, playing: boolean, rate?: number) => {
    setState(
      (prev) =>
        feedSample(prev, {
          positionS,
          wallMs: Date.now(),
          playing,
          ...(rate !== undefined ? { rate } : {}),
        }).state,
    );
  }, []);

  const reset = useCallback(() => {
    clearVideoProgress(kidId, cardId);
    setState(initProgress(durationS));
  }, [kidId, cardId, durationS]);

  return {
    unlocked: state.unlocked,
    acceptedS: state.acceptedS,
    durationS: state.durationS,
    resumeS: resumePosition(stateRef.current),
    sample,
    reset,
  };
}
