/**
 * YouTube ID canonicalizer (video spec v1.1 C2, Y9). Admission takes a bare
 * 11-character ID or one of three approved URL shapes and reduces every form
 * to the bare ID. Every other host or shape - including any nocookie host
 * (ISP-DNS-blocked on the founder's own connection, spec section 0), playlists,
 * channels, shorts, and timestamped URLs - is refused with a typed reason and
 * never reaches a shelf.
 */

export type YouTubeRefusal =
  | "empty"
  | "not-a-youtube-host"
  | "nocookie-forbidden"
  | "unsupported-youtube-path"
  | "playlist-or-channel"
  | "shorts-unsupported"
  | "timestamps-unsupported"
  | "bad-id-shape"
  | "unparseable-url";

export type CanonicalizeResult =
  { ok: true; videoId: string } | { ok: false; reason: YouTubeRefusal };

const ID_SHAPE = /^[A-Za-z0-9_-]{11}$/;

const APPROVED_HOSTS = new Set([
  "youtube.com",
  "www.youtube.com",
  "m.youtube.com",
  "youtu.be",
  "www.youtu.be",
]);

export function isYouTubeId(value: string): boolean {
  return ID_SHAPE.test(value);
}

export function canonicalizeYouTubeInput(raw: string): CanonicalizeResult {
  const input = raw.trim();
  if (input.length === 0) return { ok: false, reason: "empty" };

  // Bare ID fast path.
  if (ID_SHAPE.test(input)) return { ok: true, videoId: input };

  let url: URL;
  try {
    url = new URL(input);
  } catch {
    return { ok: false, reason: "unparseable-url" };
  }

  if (url.protocol !== "https:" && url.protocol !== "http:") {
    return { ok: false, reason: "unparseable-url" };
  }

  const host = url.hostname.toLowerCase();

  // Any nocookie host is forbidden outright (spec v1.1 section 1, R2).
  if (host.includes("youtube-nocookie")) return { ok: false, reason: "nocookie-forbidden" };

  if (!APPROVED_HOSTS.has(host)) return { ok: false, reason: "not-a-youtube-host" };

  // Timestamped URLs are refused at admission (C2).
  if (url.searchParams.has("t") || url.hash.startsWith("#t=")) {
    return { ok: false, reason: "timestamps-unsupported" };
  }

  // Playlists and channels never canonicalize to a single video.
  if (url.pathname.startsWith("/playlist") || url.searchParams.has("list")) {
    return { ok: false, reason: "playlist-or-channel" };
  }
  if (
    url.pathname.startsWith("/channel/") ||
    url.pathname.startsWith("/c/") ||
    url.pathname.startsWith("/user/") ||
    url.pathname.startsWith("/@")
  ) {
    return { ok: false, reason: "playlist-or-channel" };
  }
  if (url.pathname.startsWith("/shorts/")) return { ok: false, reason: "shorts-unsupported" };

  let candidate: string | null = null;
  if (host.endsWith("youtu.be")) {
    candidate = url.pathname.replace(/^\/+/, "").split("/")[0] ?? null;
  } else if (url.pathname === "/watch") {
    candidate = url.searchParams.get("v");
  } else if (url.pathname.startsWith("/embed/")) {
    candidate = url.pathname.split("/")[2] ?? null;
  } else {
    return { ok: false, reason: "unsupported-youtube-path" };
  }

  if (candidate && ID_SHAPE.test(candidate)) return { ok: true, videoId: candidate };
  return { ok: false, reason: "bad-id-shape" };
}
