import { useEffect, useRef, useState, type CSSProperties } from "react";

export const HOME_PREVIEW_PATH = "/preview/home-v0.2";

/** Resolve a public pathname inside Vite's configured deployment base. */
export function isHomePreviewPath(pathname: string, baseUrl: string): boolean {
  const basePath = `/${baseUrl.split("/").filter(Boolean).join("/")}`;
  if (basePath !== "/" && pathname !== basePath && !pathname.startsWith(`${basePath}/`)) {
    return false;
  }
  const withoutBase = basePath === "/" ? pathname : pathname.slice(basePath.length);
  const route = withoutBase.startsWith("/") ? withoutBase : `/${withoutBase}`;
  return route.replace(/\/$/, "") === HOME_PREVIEW_PATH;
}

export function homePreviewBootstrap(
  pathname: string,
  search: string,
  baseUrl: string,
): HomePreviewConfig | null {
  return isHomePreviewPath(pathname, baseUrl) ? parseHomePreviewConfig(search) : null;
}
const THEMES = ["clay", "lantern", "inkverse", "chalkboard"] as const;
const STATES = ["home", "celebrating", "attract"] as const;
const BANDS = ["46", "710"] as const;

type Theme = (typeof THEMES)[number];
type PreviewState = (typeof STATES)[number];
type Band = (typeof BANDS)[number];
export interface HomePreviewConfig {
  theme: Theme;
  state: PreviewState;
  band: Band;
  pack: "nila-v02";
  zigscale: number;
}

const enumValue = <T extends string>(value: string | null, values: readonly T[], fallback: T): T =>
  value !== null && values.includes(value as T) ? (value as T) : fallback;

export function parseHomePreviewConfig(search: string): HomePreviewConfig {
  const query = new URLSearchParams(search);
  const rawScale = Number(query.get("zigscale") ?? "1");
  const aligned = Math.abs(rawScale * 20 - Math.round(rawScale * 20)) < 1e-9;
  return {
    theme: enumValue(query.get("theme"), THEMES, "clay"),
    state: enumValue(query.get("state"), STATES, "home"),
    band: enumValue(query.get("band"), BANDS, "710"),
    pack: enumValue(query.get("pack"), ["nila-v02"] as const, "nila-v02"),
    zigscale:
      Number.isFinite(rawScale) && rawScale >= 1 && rawScale <= 1.6 && aligned ? rawScale : 1,
  };
}

