function Tile({
  id,
  title,
  paid,
  art,
  locked = false,
}: {
  id: string;
  title: string;
  paid: boolean;
  art: string;
  locked?: boolean;
}) {
  const [selected, setSelected] = useState(false);
  return (
    <button
      className={`home-tile${locked ? " home-tile-locked" : ""}${selected ? " home-tile-selected" : ""}`}
      id={`home-tile-${id}`}
      disabled={locked}
      onClick={locked ? undefined : () => setSelected((value) => !value)}
      aria-pressed={locked ? undefined : selected}
    >
      <span className="home-tile-art" style={{ "--art": art } as CSSProperties}>
        {locked ? (
          <span className="home-tile-sprout" aria-hidden="true">
            🌱
          </span>
        ) : null}
      </span>
      <span className={`home-tile-star${paid ? " paid" : ""}`}>
        <Star />
      </span>
      <span className="home-tile-title">{locked ? "Growing" : title}</span>
    </button>
  );
}

export function HomePreview({ config }: { config: HomePreviewConfig }) {
  const root = useRef<HTMLElement>(null);
  const celebrating = config.state === "celebrating";
  const attract = config.state === "attract";
  const artMode = celebrating ? "celebrating" : attract ? "pointing" : "base";
  const copy = COPY[config.band];

  useEffect(() => {
    const node = root.current;
    if (!node) return;
    const enabled = () =>
      Array.from(node.querySelectorAll<HTMLButtonElement>(".home-tile:not(:disabled)"));
    const first = enabled()[0];
    if (!attract && first) first.focus({ preventScroll: true });
    const onKey = (event: KeyboardEvent) => {
      if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) return;
      const tiles = enabled();
      const at = tiles.indexOf(document.activeElement as HTMLButtonElement);
      if (at < 0) return;
      event.preventDefault();
      const delta = event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 1;
      tiles[(at + delta + tiles.length) % tiles.length]?.focus({ preventScroll: true });
    };
    node.addEventListener("keydown", onKey);
    return () => node.removeEventListener("keydown", onKey);
  }, [attract]);

  const hero = (
    <div className={`home-hero${attract ? " home-attract" : ""}`}>
      {CHARACTERS.map(({ id, name, anchor }, index) => (
        <div
          key={id}
          className={`home-char${anchor ? " home-anchor" : ""}${id === "zig" ? " home-zig" : ""}${celebrating ? " home-celebrate" : ""}`}
          data-char={id}
          style={{ "--i": index, "--zig-scale": config.zigscale } as CSSProperties}
        >
          <img src={ART[id][artMode]} alt={name} draggable={false} />
          <span className="home-char-name">{name}</span>
        </div>
      ))}
    </div>
  );
  const shelf = (label: string, children: React.ReactNode) => (
    <section className="home-shelf" aria-label={label}>
      <h2 className="home-shelf-title">{label}</h2>
      <div className="home-tiles">{children}</div>
    </section>
  );

  return (
    <>
      <div id="preview-review-chrome" role="note">
        HOME-V0.2 PREVIEW
      </div>
      <main
        ref={root}
        className={`brave-screen home-screen home-preview-root theme-${config.theme}`}
        data-preview-pack={config.pack}
        data-preview-state={config.state}
      >
        {attract ? (
          <>
            {hero}
            <p className="home-attract-cue">Press any button to play</p>
            <div className="home-logo" aria-label="Nila">
              nila
            </div>
          </>
        ) : (
          <>
            <header className="home-top">
              <div className="home-hi">
                <h1 className="home-title">Hi, friend!</h1>
                <p className="home-sub">{copy.sub}</p>
              </div>
              <div className="home-stars" aria-label={`${celebrating ? 43 : 42} stars`}>
                <Star />
                <span className="home-stars-n">{celebrating ? 43 : 42}</span>
              </div>
              <div className="home-logo" aria-label="Nila">
                nila
              </div>
            </header>
            {hero}
            <div className="home-shelves">
              {shelf(
                copy.week,
                WEEK.map((tile) => (
                  <Tile
                    key={tile.id}
                    {...tile}
                    paid={tile.paid || (celebrating && tile.id === "w1")}
                  />
                )),
              )}
              {shelf(
                copy.world,
                WORLD.map((tile) => <Tile key={tile.id} {...tile} />),
              )}
              {shelf(
                copy.soon,
                ["l0", "l1"].map((id) => (
                  <Tile key={id} id={id} title="Growing" paid={false} art="#5a4fa8" locked />
                )),
              )}
            </div>
          </>
        )}
      </main>
    </>
  );
}
