/**
 * Offline (user-flows-kid R53): the shelf stays readable and marks land with
 * no network; queued completions sync when the TV is back. IndexedDB is the
 * store; the service worker (public/sw.js) keeps the app shell and character
 * art warm.
 */

const DB_NAME = "nila";
const DB_VERSION = 3;

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      const tx = req.transaction;
      if (!tx) return;
      if (!db.objectStoreNames.contains("shelves")) db.createObjectStore("shelves");
      // v3 (2026-09-12, F12): the completions outbox keyed on queuedAt
      // (Date.now(), millisecond resolution) - two writes in the same ms
      // collided and the second completion was silently lost. Mirror the
      // telemetry outbox: auto-increment keys, no collision window. Entries
      // queued under the old key are carried across in key order, which
      // preserves their insertion order.
      if (db.objectStoreNames.contains("completions")) {
        const carry: QueuedCompletion[] = [];
        const cursorReq = tx.objectStore("completions").openCursor();
        cursorReq.onsuccess = () => {
          const cursor = cursorReq.result;
          if (cursor) {
            carry.push(cursor.value as QueuedCompletion);
            cursor.continue();
          } else {
            db.deleteObjectStore("completions");
            const fresh = db.createObjectStore("completions", {
              keyPath: "id",
              autoIncrement: true,
            });
            for (const entry of carry) fresh.add(entry);
          }
        };
      } else {
        db.createObjectStore("completions", { keyPath: "id", autoIncrement: true });
      }
      // v2 (2026-09-12): telemetry outbox - a failed or offline send queues
      // here and drains on the next successful one, so offline opens and
      // views still attribute. Auto-increment keys: no collision window.
      if (!db.objectStoreNames.contains("telemetry")) {
        db.createObjectStore("telemetry", { keyPath: "id", autoIncrement: true });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export interface QueuedCompletion {
  /** Auto-assigned on write (autoIncrement); present on every drained entry. */
  id?: number;
  queuedAt: number;
  cardId: string;
  kidId: string;
  action: "i-did-it" | "undo";
  /** I-0042: quiz marks replay with their committed answer. */
  answerId?: string;
}

export async function cacheShelf(kidId: string, shelfJson: string): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("shelves", "readwrite");
    tx.objectStore("shelves").put(shelfJson, kidId);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function readCachedShelf(kidId: string): Promise<string | null> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("shelves", "readonly");
    const req = tx.objectStore("shelves").get(kidId);
    req.onsuccess = () => resolve((req.result as string | undefined) ?? null);
    req.onerror = () => reject(req.error);
  });
}

export async function queueCompletion(entry: QueuedCompletion): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("completions", "readwrite");
    tx.objectStore("completions").add(entry);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

/** A synced (or definitively refused) entry leaves the queue (F3). */
export async function removeCompletion(id: number): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("completions", "readwrite");
    tx.objectStore("completions").delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export async function drainCompletions(): Promise<QueuedCompletion[]> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("completions", "readonly");
    const req = tx.objectStore("completions").getAll();
    req.onsuccess = () => resolve(req.result as QueuedCompletion[]);
    req.onerror = () => reject(req.error);
  });
}

/** A telemetry event that missed its send (offline, dropped request). */
export interface QueuedTelemetryEvent {
  id?: number;
  kind: string;
  screen: string;
  kidId?: string;
  cardId?: string;
  detail?: Record<string, string | number | boolean>;
  queuedAt: number;
}

export async function queueTelemetryEvent(entry: QueuedTelemetryEvent): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("telemetry", "readwrite");
    tx.objectStore("telemetry").add(entry);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

/** Oldest-first: getAll returns records in key (insertion) order. */
export async function drainTelemetryEvents(): Promise<QueuedTelemetryEvent[]> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("telemetry", "readonly");
    const req = tx.objectStore("telemetry").getAll();
    req.onsuccess = () => resolve(req.result as QueuedTelemetryEvent[]);
    req.onerror = () => reject(req.error);
  });
}

export async function removeTelemetryEvent(id: number): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("telemetry", "readwrite");
    tx.objectStore("telemetry").delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}
