/* Day-close pending flag (DS-1 production walkthrough 2026-09-21: 5/5 never
   fired "All done for today!"). The final completion of the day ARMS exactly
   one fire; the fire is TAKEN (consumed) when the cleared shelf shows, so the
   moment lands exactly once and a reload between completion and fire loses
   nothing (the flag rides household-local storage like the welcome flags,
   DPDP-consistent). Deterministic next-day reset comes from server truth: a
   shelf that is not all done (a fresh day's cards, an undo, a refused ghost
   mark resynced away) CLEARS the arm, so a stale arm can never fire on a
   later day. Old-WebView safe: plain localStorage, no modern APIs. */
const KEY_PREFIX = "nila:all-done:";

const storage = (): Storage | undefined =>
  typeof localStorage !== "undefined"
    ? localStorage
    : (globalThis as { localStorage?: Storage }).localStorage;

export function markAllDonePending(kidId: string): void {
  if (!kidId) return;
  try {
    storage()?.setItem(KEY_PREFIX + kidId, "1");
  } catch {
    /* storage full/blocked: the arm is lost, so the day close does NOT fire - fail-safe toward a missed close, never a wrong one */
  }
}

/** Read-and-consume: true exactly once per armed day close. */
export function takeAllDonePending(kidId: string): boolean {
  if (!kidId) return false;
  try {
    const armed = storage()?.getItem(KEY_PREFIX + kidId) === "1";
    if (armed) storage()?.removeItem(KEY_PREFIX + kidId);
    return armed;
  } catch {
    return false;
  }
}

export function clearAllDonePending(kidId: string): void {
  if (!kidId) return;
  try {
    storage()?.removeItem(KEY_PREFIX + kidId);
  } catch {
    /* storage full/blocked: the clear is lost for this pass; the shelf-load resync retries it */
  }
}

/** Server truth: the day close only exists on a non-empty all-done shelf. */
export function allCardsDone(cards: readonly { done: boolean }[]): boolean {
  return cards.length > 0 && cards.every((c) => c.done);
}
