/**
 * The celebration moment (celebrations.design.collab.md r4 + visual v1.0d).
 * One star-minting completion fires exactly one moment, always the same size:
 * press acknowledge -> the star journey (fixed, unskippable, unoccluded) ->
 * one drawn concept on the shared 1500ms envelope -> the warm close, which
 * holds until the kid presses on (idle never auto-dismisses the win).
 * Nila is fixed cast in every concept (canon); JACKPOT is deterministic on
 * the weekly-line crossing only. The moment carries no controls - undo lives
 * one press away on the completed card.
 *
 * Concept visuals: the VD's production package - procedural C1/C3/C5 in
 * styles/celebrations-c1-c3-c5.css (base styles ARE the settle state; the
 * R23 reduced-motion frames come from its media query), C4 rasters at
 * assets/celebrations/c4-plant-<theme>-stage<1-3>.webp (only the active
 * theme's set loads), C2/C6 hero = canon elephant-cheer.png.
 */
import { useEffect, useRef, useState, type CSSProperties } from "react";
import type { ScreenDefinition } from "../state/screens";
import { telemetry } from "../api/telemetry";
import { Focusable } from "../focus/FocusRoot";
import { mapRemoteKey } from "../focus/SpatialNav";
import { assetUrl, STAR } from "./art";
import "../styles/celebrations-c1-c3-c5.css";

type CelebrationScreen = Extract<ScreenDefinition, { kind: "celebration" }>;

const NILA_STAND = "assets/characters/elephant-stand.png";
const NILA_CHEER = "assets/characters/elephant-cheer.png";
const c4Stage = (theme: string, stage: number) =>
  `assets/celebrations/c4-plant-${theme}-stage${stage}.webp`;

/** The app's active theme (single-theme builds read "clay"); only the active
 * theme's C4 raster set ever loads. */
const activeTheme = (): string => {
  if (typeof document === "undefined") return "clay";
  const m = document.documentElement.className.match(/theme-(\w+)/);
  return m?.[1] ?? "clay";
};

const density = (stars: number) => Math.min(3, Math.max(1, stars));

function NilaPresence() {
  return <img className="cele-actor cele-nila" src={assetUrl(NILA_STAND)} alt="" />;
}

/* C1 CONFETTI BLOOM: 12/18/24 pieces by star value; per-piece --dx/--dy/--rot
   set inline at draw time, capped inside the stage box (R14).
   faceClear (jackpot only, v1.1 face-zone no-draw bar): the mascot-lead's
   face - cheeks/mouth/trunk - occupies the upper band of the lead box; any
   piece whose settle box (including its glow/edge margin) would overlay
   that zone is re-seeded deterministically, first to the open right sky,
   else dropped fully below the zone. Same count, colors, delays, envelope.
   Zone rect derives from elephant-cheer.png alpha inspection (2026-09-15):
   head+trunk band = alpha x 0-84%, y 0-44%; the alpha maps to the lead box
   (>520: 56vh tall; <=520 fold: 44vh) anchored stage-left 12%, bottom 0. */
function ConfettiBloom({
  stars,
  hideNila = false,
  faceClear = false,
}: {
  stars: number;
  hideNila?: boolean;
  faceClear?: boolean;
}) {
  const count = 6 * (density(stars) + 1);
  const zone = (() => {
    if (!faceClear || typeof window === "undefined") return null;
    const vw = window.innerWidth / 100;
    const vh = window.innerHeight / 100;
    const box = (window.innerWidth > 520 ? 56 : 44) * vh;
    const boxLeft = (5 + 0.12 * 90) * vw;
    const boxTop = 65 * vh - box;
    const ax = 0.153 * box;
    const aw = 0.691 * box;
    const ay = 0.114 * box;
    const ah = 0.77 * box;
    return {
      x0: boxLeft + ax,
      x1: boxLeft + ax + 0.84 * aw,
      y0: boxTop + ay,
      y1: boxTop + ay + 0.44 * ah,
      R: 6 * vh, // piece half-size 3vh + lantern glow 2.2vh + inkverse shadow 0.8vh, rounded up
      vw,
      vh,
    };
  })();
  const hits = (dx: number, dy: number): boolean => {
    if (!zone) return false;
    const cx = 50 * zone.vw + dx * zone.vh;
    const cy = 45.75 * zone.vh + dy * zone.vh;
    return (
      cx + zone.R > zone.x0 &&
      cx - zone.R < zone.x1 &&
      cy + zone.R > zone.y0 &&
      cy - zone.R < zone.y1
    );
  };
  return (
    <div className="cele-stage" aria-hidden>
      {hideNila ? null : <NilaPresence />}
      {Array.from({ length: count }, (_, i) => {
        let dx = ((i * 53) % 62) - 31;
        let dy = ((i * 37) % 26) - 13;
        if (zone && hits(dx, dy)) {
          const rightSky = 17 + ((i * 29) % 13);
          if (!hits(rightSky, dy)) dx = rightSky;
          else dy = Math.ceil((zone.y1 + zone.R) / zone.vh - 45.75);
        }
        return (
          <span
            key={i}
            className="cele-actor c1-piece"
            style={
              {
                "--dx": `${dx}vh`,
                "--dy": `${dy}vh`,
                "--rot": `${(i * 47) % 300}deg`,
                animationDelay: `${250 + (i % 8) * 60}ms`,
              } as CSSProperties
            }
          />
        );
      })}
    </div>
  );
}

/* C3 FIREWORK FOUNTAIN: one large slow bloom per star, staggered 150ms. */
function FireworkFountain({ stars, hideNila = false }: { stars: number; hideNila?: boolean }) {
  return (
    <div className="cele-stage" aria-hidden>
      {hideNila ? null : <NilaPresence />}
      {Array.from({ length: density(stars) }, (_, i) => (
        <span key={i} className="cele-actor c3-ring" style={{ animationDelay: `${i * 150}ms` }} />
      ))}
    </div>
  );
}

/* C4 GROWING THING: theme-matched rasters, one stage per ~200ms; the lantern
   variant (top-anchored hanging bloom) is named in the VD's CSS. The still
   frame is the full stage-N plant. */
function GrowingThing({ stars, still }: { stars: number; still: boolean }) {
  const finalStage = density(stars);
  const [stage, setStage] = useState(still ? finalStage : 1);
  useEffect(() => {
    if (still) {
      setStage(finalStage);
      return;
    }
    if (stage >= finalStage) return;
    const t = setTimeout(() => setStage((s) => Math.min(finalStage, s + 1)), 200);
    return () => clearTimeout(t);
  }, [stage, finalStage, still]);
  const theme = activeTheme();
  return (
    <div className="cele-stage" aria-hidden>
      <NilaPresence />
      <div className={`cele-actor c4-plant${stage < finalStage ? " growing" : ""}`}>
        <img src={assetUrl(c4Stage(theme, stage))} alt="" />
      </div>
    </div>
  );
}

/* C5 SHAPE HOP: one big shape per star, staggered 150ms, settling centered. */
function ShapeHop({ stars }: { stars: number }) {
  const n = density(stars);
  return (
    <div className="cele-stage" aria-hidden>
      <NilaPresence />
      {Array.from({ length: n }, (_, i) => (
        <span
          key={i}
          /* Fly-sprite ruling (PM 2026-09-14): the cycle starts on the GOLD
             CIRCLE - a 1-star moment's only shape reads as the win, never a
             bare square (VD may re-skin the square in its next pass). */
          className={`cele-actor c5-shape${i % 3 === 0 ? " c5-shape--circle" : ""}${i % 3 === 1 ? " c5-shape--triangle" : ""}`}
          style={
            {
              /* --slot-step comes from CSS (16vh default; 11vh in the <=520
                 fold) so the hop keyframes and the settle state agree. */
              "--slot-i": `${i - (n - 1) / 2}`,
              "--slot-x": `calc(var(--slot-i) * var(--slot-step, 16vh))`,
              animationDelay: `${i * 150}ms`,
            } as CSSProperties
          }
        />
      ))}
    </div>
  );
}

/* C2 MASCOT BIG: the elephant IS the moment (40-46vh, center-left); 2-star
   adds one sparkle beside her, 3-star adds two. */
function MascotBig({ stars }: { stars: number }) {
  return (
    <div className="cele-stage" aria-hidden>
      <img className="cele-actor cele-nila cele-nila--lead" src={assetUrl(NILA_CHEER)} alt="" />
      {Array.from({ length: density(stars) - 1 }, (_, i) => (
        <img
          key={i}
          className={`nila-cel-sparkle nila-cel-sparkle-${i}`}
          src={assetUrl(STAR)}
          alt=""
        />
      ))}
    </div>
  );
}

function ConceptBody({ screen, still }: { screen: CelebrationScreen; still: boolean }) {
  const stars = screen.starsEarned || screen.card.baseStars || 1;
  switch (screen.concept) {
    case "confetti-bloom":
      return <ConfettiBloom stars={stars} />;
    case "firework-fountain":
      return <FireworkFountain stars={stars} />;
    case "growing-thing":
      return <GrowingThing stars={stars} still={still} />;
    case "shape-hop":
      return <ShapeHop stars={stars} />;
    case "mascot-big":
      return <MascotBig stars={stars} />;
    case "jackpot":
      // R16: layered mascot + bloom + fountain, denser, same envelope.
      // v1.0f C6 composition pin: a SINGLE mascot-lead Nila - the scene-layer
      // presence is suppressed; the jackpot layers C2's pose with scene
      // EFFECTS (confetti bloom + one ring per star), never a second elephant.
      return (
        <>
          <MascotBig stars={stars} />
          <ConfettiBloom stars={Math.min(3, stars + 1)} hideNila faceClear />
          <FireworkFountain stars={stars} hideNila />
        </>
      );
    default:
      return null; // concept lands with the completion verdict
  }
}

export function CelebrationMoment({
  screen,
  onExit,
}: {
  screen: CelebrationScreen;
  onExit: () => void;
}) {
  const startRef = useRef(Date.now());
  const [phase, setPhase] = useState<"play" | "close">(
    screen.shotHold === "close" ? "close" : "play",
  );
  const skippedRef = useRef(false);
  const skipAtRef = useRef<number | null>(null);
  const emittedRef = useRef(false);
  const [reduced] = useState(
    () => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false,
  );

  // The envelope ends composed: the warm close owns a still screen from ~2.5s.
  useEffect(() => {
    if (reduced) {
      setPhase("close");
      return;
    }
    // Shot fixtures pin the phase: no envelope timer while held.
    if (screen.shotHold) return;
    const t = setTimeout(() => setPhase("close"), 2500);
    return () => clearTimeout(t);
  }, [reduced, screen.shotHold]);

  // R20 input gate: before 1.2s presses are swallowed; during the rest of the
  // envelope one press snaps to the still close; on the still any press exits.
  // One press, one transition - held keys never repeat into skips. Capture
  // phase, so the moment owns every key while it is on screen (R7).
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (mapRemoteKey(e.key).type === "ignored") return;
      e.preventDefault();
      e.stopImmediatePropagation();
      if (e.repeat) return;
      const elapsed = Date.now() - startRef.current;
      if (!reduced && elapsed < 1200) return; // swallowed: the star must land first
      if (phase === "play") {
        skippedRef.current = true;
        skipAtRef.current = elapsed;
        setPhase("close");
        return;
      }
      onExit();
    };
    window.addEventListener("keydown", handler, { capture: true });
    return () => window.removeEventListener("keydown", handler, { capture: true });
  }, [phase, reduced, onExit]);

  // R24: every moment emits celebration_shown once with its draw context -
  // at the close (skip flag settled) or on an interruption unmount (R22).
  const concept = screen.concept;
  useEffect(() => {
    if (!concept) return;
    const emit = () => {
      if (emittedRef.current) return;
      emittedRef.current = true;
      telemetry("celebration_shown", "celebration", {
        kidId: screen.kidId,
        detail: {
          concept,
          theme: activeTheme(),
          starValue: screen.starsEarned,
          exclusions: screen.excluded ?? "",
          skipped: skippedRef.current,
          skipTimestamp: skipAtRef.current ?? 0,
          pendingSync: screen.pendingSync === true,
        },
      });
    };
    if (phase === "close") emit();
    return () => emit();
  }, [concept, phase, screen.kidId, screen.starsEarned, screen.excluded, screen.pendingSync]);

  const stars = screen.starsEarned;
  const name = screen.kidName;
  const wallet = screen.walletAfter;
  const left = screen.cardsLeftToday;
  const still = reduced || phase === "close" || screen.shotHold === "play";

  // TRIP-3 (critic round 2026-09-13): the moment was a dead-end - no button,
  // no auto-advance. Once the close state shows, the moment leaves on its own
  // after a beat (6s); any press still beats the timer.
  const onExitRef = useRef(onExit);
  onExitRef.current = onExit;
  useEffect(() => {
    if (phase !== "close") return;
    if (screen.shotHold) return; // held cells never auto-exit mid-capture
    const t = window.setTimeout(() => onExitRef.current(), 6000);
    return () => window.clearTimeout(t);
  }, [phase, screen.shotHold]);

  return (
    <main
      className={`nila-screen nila-moment${phase === "close" ? " nila-moment-closed" : ""}${screen.shotHold ? " nila-moment-shot-still" : ""}${concept ? ` nila-moment-${concept}` : ""}`}
      onClick={() => {
        // The whole screen is the one OK target (R15/R20) - pointer parity.
        const elapsed = Date.now() - startRef.current;
        if (!reduced && elapsed < 1200) return;
        if (phase === "play") {
          skippedRef.current = true;
          skipAtRef.current = elapsed;
          setPhase("close");
        } else onExit();
      }}
    >
      <div className="nila-cel-tint" aria-hidden />
      {/* R14: the star journey is the one fixed beat - one straight corridor
          to the HUD corner, rendered above the body, the count ticking once. */}
      <img className="nila-cel-star" src={assetUrl(STAR)} alt="" />
      <div className="nila-cel-count" aria-hidden>
        {screen.pendingSync ? "⭐ …" : `⭐ ${wallet ?? stars}`}
      </div>
      {concept ? <ConceptBody screen={screen} still={still} /> : null}
      <div className={`nila-cel-close${phase === "close" ? " nila-cel-close-on" : ""}`}>
        <h1 className="nila-title">
          {screen.crossedLine
            ? `You crossed the line - ${screen.lineRewardTitle ?? "your reward"} is yours`
            : `You did it${name ? `, ${name}` : ""}!`}
        </h1>
        {screen.pendingSync ? (
          <>
            <p className="nila-stars">Will count when you're back</p>
            <p className="nila-calm">Your win is safe on this TV.</p>
            {/* TRIP-3: the offline branch was the same dead-end. */}
            <div onClick={(e) => e.stopPropagation()}>
              <Focusable id="moment-back" className="nila-action nila-primary" onOk={onExit}>
                Back to my day
              </Focusable>
            </div>
          </>
        ) : (
          <>
            {stars > 0 ? (
              <p className="nila-stars">
                <img src={assetUrl(STAR)} alt="" /> +{stars}
              </p>
            ) : null}
            {wallet !== undefined ? (
              <p className="nila-calm">
                You have {wallet} {wallet === 1 ? "star" : "stars"} · "{screen.card.title}" - all
                you.
              </p>
            ) : null}
            {left !== undefined ? (
              <p className="nila-calm">
                {left === 0 ? "That was the last one for today." : `${left} left today.`}
              </p>
            ) : null}
            {/* TRIP-3 (critic round 2026-09-13): a visible next action once the
                close state shows - kids sat 9+ seconds with no affordance. */}
            {/* The wrapper swallows the click so it does not also reach the
                moment's whole-screen onClick (double leave dispatch). */}
            <div onClick={(e) => e.stopPropagation()}>
              <Focusable id="moment-back" className="nila-action nila-primary" onOk={onExit}>
                Back to my day
              </Focusable>
            </div>
          </>
        )}
      </div>
    </main>
  );
}
