/**
 * Timer persistence (spec v3-r "Durable record"; T15 + PM re-rule 2026-09-25:
 * dedicated IndexedDB database `nila-timer`, version 1, no store reuse - never
 * touches the offline "nila" database).
 *
 * One key, `active-v1`. Every write: canonicalize -> one readwrite put/delete
 * -> await transaction oncomplete -> NEW readonly transaction -> readback ->
 * revalidate -> compare every canonical field. Any failure is a typed error;
 * the caller shows the "can't start yet" / recovery copy. No timer math here.
 */
import {
  TIMER_RECORD_KEY,
  canonicalizeTimerRecord,
  timerRecordsEqual,
  validateTimerRecord,
  type TimerRecord,
} from "../../../../packages/domain/src/timer";

export const TIMER_DB_NAME = "nila-timer";
export const TIMER_DB_VERSION = 1;
export const TIMER_STORE = "timer";

export type TimerStorageErrorCode =
  | "unavailable"
  | "open-failed"
  | "blocked"
  | "quota"
  | "security"
  | "abort"
  | "readback-missing"
  | "readback-mismatch"
  | "readback-present"
  | "invalid";

export class TimerStorageError extends Error {
  constructor(
    readonly code: TimerStorageErrorCode,
    message?: string,
  ) {
    super(message ?? code);
    this.name = "TimerStorageError";
  }
}

export type TimerLoadResult =
  { kind: "empty" } | { kind: "ok"; record: TimerRecord } | { kind: "corrupt" };

function classify(err: unknown, fallback: TimerStorageErrorCode): TimerStorageErrorCode {
  const name = (err as { name?: string } | null)?.name;
  if (name === "QuotaExceededError") return "quota";
  if (name === "SecurityError") return "security";
  if (name === "AbortError") return "abort";
  return fallback;
}

export class TimerStorage {
  private dbPromise: Promise<IDBDatabase> | null = null;

  constructor(private readonly factory: IDBFactory | undefined = globalThis.indexedDB) {}

  private open(): Promise<IDBDatabase> {
    if (this.dbPromise) return this.dbPromise;
    const factory = this.factory;
    if (!factory) return Promise.reject(new TimerStorageError("unavailable"));
    const p = new Promise<IDBDatabase>((resolve, reject) => {
      let req: IDBOpenDBRequest;
      try {
        req = factory.open(TIMER_DB_NAME, TIMER_DB_VERSION);
      } catch (err) {
        reject(new TimerStorageError(classify(err, "open-failed")));
        return;
      }
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(TIMER_STORE)) db.createObjectStore(TIMER_STORE);
      };
      req.onblocked = () => reject(new TimerStorageError("blocked"));
      req.onerror = () => reject(new TimerStorageError(classify(req.error, "open-failed")));
      req.onsuccess = () => {
        const db = req.result;
        db.onversionchange = () => {
          db.close();
          this.dbPromise = null;
        };
        resolve(db);
      };
    });
    // A failed open must not poison later attempts ("Try again in a moment").
    this.dbPromise = p.catch((err) => {
      this.dbPromise = null;
      throw err;
    });
    return this.dbPromise;
  }

  /** Raw read in its own readonly transaction; resolves after the tx completes. */
  private async readRaw(): Promise<unknown> {
    const db = await this.open();
    return new Promise<unknown>((resolve, reject) => {
      let tx: IDBTransaction;
      try {
        tx = db.transaction(TIMER_STORE, "readonly");
      } catch (err) {
        reject(new TimerStorageError(classify(err, "abort")));
        return;
      }
      let value: unknown;
      const req = tx.objectStore(TIMER_STORE).get(TIMER_RECORD_KEY);
      req.onsuccess = () => {
        value = req.result;
      };
      tx.oncomplete = () => resolve(value);
      tx.onabort = () => reject(new TimerStorageError(classify(tx.error, "abort")));
      tx.onerror = () => reject(new TimerStorageError(classify(tx.error, "abort")));
    });
  }

  private async commit(op: (store: IDBObjectStore) => void): Promise<void> {
    const db = await this.open();
    await new Promise<void>((resolve, reject) => {
      let tx: IDBTransaction;
      try {
        tx = db.transaction(TIMER_STORE, "readwrite");
        op(tx.objectStore(TIMER_STORE));
      } catch (err) {
        reject(new TimerStorageError(classify(err, "abort")));
        return;
      }
      tx.oncomplete = () => resolve();
      tx.onabort = () => reject(new TimerStorageError(classify(tx.error, "abort")));
      tx.onerror = () => reject(new TimerStorageError(classify(tx.error, "abort")));
    });
  }

  async load(): Promise<TimerLoadResult> {
    const raw = await this.readRaw();
    if (raw === undefined) return { kind: "empty" };
    const v = validateTimerRecord(raw);
    return v.ok ? { kind: "ok", record: v.record } : { kind: "corrupt" };
  }

  /** Atomic put + verified readback. Resolves with the canonical stored record. */
  async write(record: TimerRecord): Promise<TimerRecord> {
    let canonical: TimerRecord;
    try {
      canonical = canonicalizeTimerRecord(record);
    } catch {
      throw new TimerStorageError("invalid");
    }
    await this.commit((store) => {
      store.put(canonical, TIMER_RECORD_KEY);
    });
    const raw = await this.readRaw();
    if (raw === undefined) throw new TimerStorageError("readback-missing");
    const v = validateTimerRecord(raw);
    if (!v.ok || !timerRecordsEqual(v.record, canonical))
      throw new TimerStorageError("readback-mismatch");
    return v.record;
  }

  /** Delete + verified absent readback (stop, erase-and-start-fresh). */
  async erase(): Promise<void> {
    await this.commit((store) => {
      store.delete(TIMER_RECORD_KEY);
    });
    const raw = await this.readRaw();
    if (raw !== undefined) throw new TimerStorageError("readback-present");
  }

  close(): void {
    void this.dbPromise?.then((db) => db.close()).catch(() => undefined);
    this.dbPromise = null;
  }
}
