/**
 * Kid video picker (founder requirement, Sep 23): the parent stocks 1-6
 * videos on one activity; the kid browses REAL thumbnails (branded fallback
 * while they load or when one 404s) and picks with D-pad or touch. A dead or
 * embedding-disabled video shows "not available" at play time (Y7) - the
 * picker never navigates to YouTube.
 */
import { useState } from "react";
import { Focusable } from "../focus/FocusRoot";
import type {
  ActivityMedia,
  YouTubeMediaItem,
} from "../../../../packages/domain/src/video/media.ts";
import { videoThumbnailUrl } from "./youtube-player";

function PickerTile({
  media,
  index,
  onPick,
  autoFocus,
}: {
  media: ActivityMedia;
  index: number;
  onPick: (index: number) => void;
  autoFocus: boolean;
}) {
  const [thumbFailed, setThumbFailed] = useState(false);
  const item = media.items[index];
  const isYouTube = media.kind === "youtube";
  const thumb =
    isYouTube && !thumbFailed ? videoThumbnailUrl((item as YouTubeMediaItem).video_id) : null;
  return (
    <Focusable
      id={`video-pick-${index}`}
      className="nila-video-pick"
      autoFocus={autoFocus}
      onOk={() => onPick(index)}
    >
      {thumb ? (
        <img
          className="nila-video-thumb"
          src={thumb}
          alt={`Video ${index + 1}`}
          onError={() => setThumbFailed(true)}
        />
      ) : (
        <div
          className="nila-video-thumb nila-video-thumb-fallback"
          aria-label={`Video ${index + 1}`}
        >
          Video {index + 1}
        </div>
      )}
    </Focusable>
  );
}

export function VideoPicker({
  media,
  onPick,
  onExit,
}: {
  media: ActivityMedia;
  onPick: (index: number) => void;
  onExit: () => void;
}) {
  return (
    <div className="nila-video-picker">
      <h2 className="nila-video-picker-title">Pick a video</h2>
      <div className="nila-video-picker-row">
        {media.items.map((_, i) => (
          <PickerTile key={i} media={media} index={i} onPick={onPick} autoFocus={i === 0} />
        ))}
      </div>
      <Focusable id="video-picker-exit" className="nila-action nila-secondary" onOk={onExit}>
        Back
      </Focusable>
    </div>
  );
}
