/**
 * F7 one-press guard (docs/findings/2026-09-11-f7-enter-key-bleed.md):
 * one physical press causes at most one action.
 *
 * The bleed: an ok/back keydown that triggers a screen change was followed
 * by more keydowns from the SAME press (key repeat, or the tail of the
 * pair re-dispatched across the transition) landing on whatever has focus
 * on the screen it arrived on - one press, two actions, and on the
 * celebration screen that meant undo re-firing "I did it!" (a phantom go
 * on Mr. A's real shelf, 2026-09-11).
 *
 * The guard arms on the acting keydown and stays armed until the matching
 * keyup; repeats and any same-press re-dispatch are swallowed. Arrows are
 * never guarded - hold-to-move is intended. Pure logic, no DOM: FocusRoot
 * wires keyup (release) and window blur (reset, so a lost keyup can't jam
 * the remote).
 */
export class KeyPressGuard {
  private armed = new Map<string, number>();

  /** TRIP-1: a lost keyup must not jam the key forever. An arm older than
   * ttlMs is never the same physical press - it self-releases. (The blur
   * reset already covers the window-switch case; this covers the silent
   * dropped-keyup case, seen as intermittent dead OK presses.) */
  constructor(
    private now: () => number = () => Date.now(),
    private ttlMs: number = 800,
  ) {}

  /** true = this keydown may act; false = swallow it (same press still held). */
  shouldAct(key: string, repeat: boolean): boolean {
    const at = this.armed.get(key);
    if (repeat || (at !== undefined && this.now() - at < this.ttlMs)) return false;
    this.armed.set(key, this.now());
    return true;
  }

  release(key: string): void {
    this.armed.delete(key);
  }

  reset(): void {
    this.armed.clear();
  }
}
