/**
 * Direct-file media allowlist (video spec v1.1 D2, carried from v1 V1):
 * absolute https:// only, server-driven host allowlist, fail closed on any
 * redirect off-allowlist, no runtime-entered URLs, no credentials in URLs.
 * O2 (PM ruling 2026-09-23): the v1 allowlist is Supabase Storage only;
 * growing it needs a real admitted content need, not escalation.
 */

export type AllowlistRefusal =
  "not-absolute-https" | "host-not-allowed" | "credentials-in-url" | "unparseable-url";

export type AllowlistResult = { ok: true } | { ok: false; reason: AllowlistRefusal };

/**
 * The allowlist is host-suffix based so project-scoped Supabase hosts
 * (`<project>.supabase.co`) are matched by their platform suffix. Callers pin
 * the exact project host(s) at config time; this predicate never widens them.
 */
export function makeMediaHostAllowlist(allowedHosts: readonly string[]) {
  const hosts = allowedHosts.map((h) => h.toLowerCase());
  return function isAllowedMediaUrl(raw: string): AllowlistResult {
    let url: URL;
    try {
      url = new URL(raw);
    } catch {
      return { ok: false, reason: "unparseable-url" };
    }
    if (url.protocol !== "https:") return { ok: false, reason: "not-absolute-https" };
    if (url.username !== "" || url.password !== "") {
      return { ok: false, reason: "credentials-in-url" };
    }
    const host = url.hostname.toLowerCase();
    const allowed = hosts.some((h) => host === h || host.endsWith(`.${h}`));
    return allowed ? { ok: true } : { ok: false, reason: "host-not-allowed" };
  };
}

/** O2 default: Supabase Storage platform suffix only. */
export const DEFAULT_MEDIA_ALLOWLIST = makeMediaHostAllowlist(["supabase.co"]);
