/**
 * The video beat: shelf -> (picker when the activity carries 2-6 videos) ->
 * player -> Done (90% legit-played latch only) -> the same completion path
 * every card takes. Back exits to the shelf with no ceremony (leave).
 */
import { useState } from "react";
import type { CardDefinition } from "../state/screens";
import { VideoPicker } from "./VideoPicker";
import { VideoCardPlayer } from "./VideoCardPlayer";
import type { ActivityMedia } from "../../../../packages/domain/src/video/media.ts";

export function VideoScreen({
  kidId,
  card,
  onDone,
  onExit,
}: {
  kidId: string;
  card: CardDefinition & { media: ActivityMedia };
  onDone: (cardId: string) => void;
  onExit: () => void;
}) {
  // A single-video activity skips the picker - one less press, same doctrine.
  const [picked, setPicked] = useState<number | null>(card.media.items.length === 1 ? 0 : null);
  if (picked === null) {
    return (
      <main className="nila-screen nila-video-screen">
        <h1 className="nila-title">{card.title}</h1>
        <VideoPicker media={card.media} onPick={setPicked} onExit={onExit} />
      </main>
    );
  }
  return (
    <main className="nila-screen nila-video-screen">
      <h1 className="nila-title">{card.title}</h1>
      <VideoCardPlayer
        kidId={kidId}
        cardId={card.id}
        media={card.media}
        itemIndex={picked}
        onDone={() => onDone(card.id)}
        onExit={onExit}
      />
    </main>
  );
}
