/**
 * SpatialNav — the remote-first focus spine (research-k1-tv-navigation).
 *
 * The contract, all of it:
 *  - exactly one visible focus, always
 *  - arrow key = move focus one step, by screen geometry
 *  - OK = act on the focused element
 *  - Back = leave quietly (handled by the screen, not here)
 *  - no long-press, no hover, no hidden focus
 *
 * Pure logic, no DOM: elements register with an id and a rect; arrow presses
 * resolve to the nearest neighbour in that direction. Screens own what OK does.
 */

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface Focusable {
  id: string;
  rect: Rect;
  /** When false the element stays registered (keeps layout memory) but is skipped. */
  enabled?: boolean;
  /**
   * When false the element is an inert utility (timer launcher): focusable by
   * pointer and programmatic restore, but invisible to arrow traversal, the
   * first-registered auto-focus and the unmount fallback. Omitted = true, so
   * every existing registration keeps its exact behavior.
   */
  navigable?: boolean;
}

const traversable = (item: Focusable): boolean =>
  item.enabled !== false && item.navigable !== false;

export type Direction = "left" | "right" | "up" | "down";

// CSS subpixel measurements and arithmetic can drift by tiny fractions at
// a shared center. A centered vertical stack is not a sideways neighbour.
const DIRECTION_EPSILON_PX = 0.5;

const center = (r: Rect): { cx: number; cy: number } => ({
  cx: r.x + r.w / 2,
  cy: r.y + r.h / 2,
});

export class SpatialNav {
  private items = new Map<string, Focusable>();
  private focusId: string | null = null;

  register(item: Focusable): void {
    this.items.set(item.id, item);
    if (this.focusId === null && traversable(item)) {
      this.focusId = item.id;
    }
  }

  /** Refresh geometry without changing registration order or navigability. */
  updateRect(id: string, rect: Rect): void {
    const item = this.items.get(id);
    if (item) this.items.set(id, { ...item, rect });
  }

  unregister(id: string): void {
    this.items.delete(id);
    if (this.focusId === id) {
      this.focusId = this.firstEnabled()?.id ?? null;
    }
  }

  clear(): void {
    this.items.clear();
    this.focusId = null;
  }

  get focused(): string | null {
    return this.focusId;
  }

  /** Focus a specific element (e.g. screen entry lands on the primary action). */
  focus(id: string): boolean {
    const item = this.items.get(id);
    if (!item || item.enabled === false) return false;
    this.focusId = id;
    return true;
  }

  private firstEnabled(): Focusable | undefined {
    for (const item of this.items.values()) {
      if (traversable(item)) return item;
    }
    return undefined;
  }

  /**
   * Move focus one step. Returns the newly focused id, or the current id when
   * there is nothing in that direction (focus never disappears).
   *
   * `scope` (timer overlay containment, plan 51861fbc section 3.1): when given,
   * traversal considers ONLY ids in a fresh immutable snapshot of the scope
   * and fails closed - an empty scope or no in-scope candidate means no
   * movement, never a global step. A focus outside the scope is pulled to the
   * first enabled in-scope id (scope order). Undefined scope is the unchanged
   * global navigation, byte-for-byte in behavior.
   */
  move(direction: Direction, scope?: Iterable<string>): string | null {
    if (scope !== undefined) return this.moveScoped(direction, scope);
    return this.moveGlobal(direction, null);
  }

  private moveScoped(direction: Direction, scope: Iterable<string>): string | null {
    const snapshot: readonly string[] = Object.freeze([...scope]);
    const allowed = new Set(snapshot);
    const enabledInScope = snapshot.filter((id) => {
      const item = this.items.get(id);
      return item !== undefined && traversable(item);
    });
    if (enabledInScope.length === 0) return this.focusId;
    const current = this.focusId ? this.items.get(this.focusId) : undefined;
    if (!current || !allowed.has(current.id) || !traversable(current)) {
      this.focusId = enabledInScope[0] ?? this.focusId;
      return this.focusId;
    }
    return this.moveGlobal(direction, allowed);
  }

  private moveGlobal(direction: Direction, allowed: ReadonlySet<string> | null): string | null {
    const current = this.focusId ? this.items.get(this.focusId) : undefined;
    if (!current) {
      const first = this.firstEnabled();
      this.focusId = first?.id ?? null;
      return this.focusId;
    }
    const from = center(current.rect);
    let best: { id: string; score: number; dist2: number } | null = null;
    for (const item of this.items.values()) {
      if (item.id === current.id || !traversable(item)) continue;
      if (allowed !== null && !allowed.has(item.id)) continue;
      const to = center(item.rect);
      const dx = to.cx - from.cx;
      const dy = to.cy - from.cy;
      // A subpixel center drift is not a directional step. In particular,
      // same-center vertically stacked actions must never be sideways peers.
      if (direction === "left" && dx >= -DIRECTION_EPSILON_PX) continue;
      if (direction === "right" && dx <= DIRECTION_EPSILON_PX) continue;
      if (direction === "up" && dy >= -DIRECTION_EPSILON_PX) continue;
      if (direction === "down" && dy <= DIRECTION_EPSILON_PX) continue;
      // When the completed-card actions occupy the same visual row, a
      // few pixels of y drift from focus growth cannot make them Up/Down
      // neighbours. Other screens keep their established spatial scoring.
      if ((direction === "up" || direction === "down") &&
          (current.id === "back-to-my-day" && item.id === "undo-completed" ||
           current.id === "undo-completed" && item.id === "back-to-my-day")) {
        const verticalOverlap =
          Math.min(current.rect.y + current.rect.h, item.rect.y + item.rect.h) -
          Math.max(current.rect.y, item.rect.y);
        if (verticalOverlap >= 0.5 * Math.min(current.rect.h, item.rect.h) && Math.abs(dx) > Math.abs(dy))
          continue;
      }
      // Primary-axis distance dominates. Off-axis penalty: ZERO for true
      // row-mates, otherwise the larger of center drift and interval gap.
      // Row-mate = the two intervals share at least HALF of the smaller
      // one. Row-mates of different heights stay row-mates: a focused
      // card's mid-transition rect (focus growth shifts its center) must
      // not make the true next card lose to a farther one - measured on
      // the lantern centered shelf, where a stale grown-card rect (dy 89)
      // made D-pad right skip it entirely (overlap ~70% of the smaller
      // span, well past half). A merely ADJACENT row (touching, no real
      // overlap) keeps the full drift penalty, so straight-ahead still
      // beats a near-diagonal. A HAIRLINE overlap keeps it too: a
      // full-width card one row down whose registered edge brushes the
      // focused card's span by <1px (wp5 forest under chalkboard, 390
      // lantern) is not a row-mate - zeroing its penalty let its shorter
      // primary distance steal the side step when a registration
      // transient crossed the bare >0 boundary (TE independent wp5
      // rerun, 2026-09-22; flip proven at overlap 0.82px, settled gap
      // 15.18px).
      const span = (c: number, size: number): [number, number] => [c - size / 2, c + size / 2];
      const offAxis = (a: [number, number], b: [number, number], drift: number) => {
        const overlap = Math.min(a[1], b[1]) - Math.max(a[0], b[0]);
        const minSpan = Math.min(a[1] - a[0], b[1] - b[0]);
        if (overlap >= 0.5 * minSpan) return 0;
        const gap = a[1] < b[0] ? b[0] - a[1] : a[0] - b[1];
        return Math.max(drift, gap);
      };
      const primary = direction === "left" || direction === "right" ? Math.abs(dx) : Math.abs(dy);
      const off =
        direction === "left" || direction === "right"
          ? offAxis(span(from.cy, current.rect.h), span(to.cy, item.rect.h), Math.abs(dy))
          : offAxis(span(from.cx, current.rect.w), span(to.cx, item.rect.w), Math.abs(dx));
      const score = primary + off * 3;
      // Exact ties are real on symmetric layouts (two equal cards flanking a
      // centered header). Breaking them by Map insertion order made the walk
      // depend on DOM registration order - a React reorder could flip kid
      // navigation. Tie-break deterministically instead: smaller straight-line
      // center distance (the truer "one step"), then the lexicographically
      // smaller id. Geometry decides; the DOM never does.
      const dist2 = dx * dx + dy * dy;
      if (
        !best ||
        score < best.score ||
        (score === best.score &&
          (dist2 < best.dist2 || (dist2 === best.dist2 && item.id < best.id)))
      )
        best = { id: item.id, score, dist2 };
    }
    if (best) this.focusId = best.id;
    return this.focusId;
  }
}

/** Remote key event → semantic command. The only keys a TV kid ever gets. */
export type RemoteCommand =
  | { type: "move"; direction: Direction }
  | { type: "ok" }
  | { type: "back" }
  /** Timer overlay open (PM design ruling Option C, 2026-09-25): ContextMenu primary, ColorF0Red fallback. */
  | { type: "openTimerOverlay" }
  | { type: "ignored"; key: string };

/** Remote keys that open the timer overlay. Primary first. */
export const TIMER_OVERLAY_KEYS = ["ContextMenu", "ColorF0Red"] as const;

export function mapRemoteKey(key: string): RemoteCommand {
  switch (key) {
    case "ArrowLeft":
      return { type: "move", direction: "left" };
    case "ArrowRight":
      return { type: "move", direction: "right" };
    case "ArrowUp":
      return { type: "move", direction: "up" };
    case "ArrowDown":
      return { type: "move", direction: "down" };
    case "Enter":
    case " ": // some Android TV remotes deliver OK as Space
      return { type: "ok" };
    case "Escape":
    case "Backspace":
    case "BrowserBack":
      return { type: "back" };
    case "ContextMenu":
    case "ColorF0Red":
      return { type: "openTimerOverlay" };
    default:
      return { type: "ignored", key };
  }
}
