/**
 * Timer controller: the only place UI events meet storage and clocks. It
 * holds no timer math of its own - every transition is a domain function,
 * every write goes through TimerStorage's verified put. Framework-free so it
 * is unit-tested in node; the React host subscribes to snapshots.
 */
import {
  MonotonicCountdown,
  acknowledgeTimer,
  finishTimer,
  initialTimerViewState,
  newTimerId,
  pauseTimer,
  reconcileOnLoad,
  replaceTimer,
  resumeTimer,
  setPresentation,
  startTimer,
  tickAnnouncement,
  timerViewReducer,
  type TimerAnnouncement,
  type TimerEvent,
  type TimerPresentation,
  type TimerRecord,
  type TimerViewState,
} from "../../../../../packages/domain/src/timer";
import type { TimerLoadResult } from "../../state/timer-storage";

export interface TimerStoragePort {
  load(): Promise<TimerLoadResult>;
  write(record: TimerRecord): Promise<TimerRecord>;
  erase(): Promise<void>;
}

export interface TimerClocks {
  wall(): number;
  mono(): number;
}

export interface TimerCuePort {
  /** Visual finish is already persisted when this is called. */
  finish(timerId: string): void;
  stop(): void;
}

export interface TimerSnapshot {
  state: TimerViewState;
  remainingMs: number;
  busy: boolean;
  announcement: TimerAnnouncement | null;
}

export const TIMER_COPY = {
  startBlocked: "Timer can’t start yet. Nila couldn’t save it safely. Try again in a moment.",
  corruptTitle: "Timer needs a fresh start.",
  corruptBody: "Nila couldn’t safely read the saved timer. Nothing new has started.",
  eraseTitle: "Erase the saved timer?",
  keep: "Keep it",
  erase: "Erase and start fresh",
  almost: "Almost there",
  finished: "Time’s up!",
  stopTitle: "Stop the timer?",
  replaceTitle: "Start a new timer?",
} as const;

export class TimerController {
  private state: TimerViewState = initialTimerViewState;
  private countdown: MonotonicCountdown | null = null;
  private remaining = 0;
  private busy = false;
  private announcement: TimerAnnouncement | null = null;
  private listeners = new Set<(s: TimerSnapshot) => void>();
  private cueGuard = new Set<string>();
  private hidden: { mono: number; wall: number } | null = null;

  constructor(
    private readonly storage: TimerStoragePort,
    private readonly clocks: TimerClocks,
    private readonly cue: TimerCuePort,
    private readonly defaultPresentation: TimerPresentation = "racer",
    private readonly makeId: () => string = () => newTimerId(),
  ) {}

  subscribe(fn: (s: TimerSnapshot) => void): () => void {
    this.listeners.add(fn);
    fn(this.snapshot());
    return () => this.listeners.delete(fn);
  }

  snapshot(): TimerSnapshot {
    return {
      state: this.state,
      remainingMs: this.remaining,
      busy: this.busy,
      announcement: this.announcement,
    };
  }

  private emit(): void {
    const s = this.snapshot();
    for (const l of this.listeners) l(s);
  }

  private dispatch(e: TimerEvent): void {
    this.state = timerViewReducer(this.state, e);
  }

  private anchor(record: TimerRecord | null, remaining: number): void {
    this.remaining = remaining;
    this.countdown =
      record && record.status === "running"
        ? new MonotonicCountdown(remaining, this.clocks.mono(), record.presetMs)
        : null;
  }

  async load(): Promise<void> {
    let res: TimerLoadResult;
    try {
      res = await this.storage.load();
    } catch {
      // Unreadable storage at boot: nothing is running; start will surface the block.
      this.dispatch({ type: "loaded", record: null });
      this.emit();
      return;
    }
    if (res.kind === "corrupt") {
      this.anchor(null, 0);
      this.dispatch({ type: "load-corrupt" });
      this.emit();
      return;
    }
    if (res.kind === "empty") {
      this.anchor(null, 0);
      this.dispatch({ type: "loaded", record: null });
      this.emit();
      return;
    }
    const rec = reconcileOnLoad(res.record, this.clocks.wall());
    if (rec.kind === "finished") {
      let record = rec.record;
      if (rec.changed) {
        try {
          record = await this.storage.write(record);
        } catch {
          /* visual finish still shows; the next write retries */
        }
      }
      this.anchor(record, 0);
      this.dispatch({ type: "loaded", record });
      // Acknowledged finishes never replay; an unacknowledged finish that
      // happened while closed shows visually, no chime (closed-app alarm is out of scope).
      this.cueGuard.add(record.timerId);
    } else {
      this.anchor(rec.record, rec.remainingMs);
      this.dispatch({ type: "loaded", record: rec.record, remainingMs: rec.remainingMs });
    }
    this.emit();
  }

  open(): void {
    this.dispatch({ type: "open" });
    this.emit();
  }
  close(): void {
    this.dispatch({ type: "close" });
    this.emit();
  }
  back(): void {
    this.cue.stop();
    this.dispatch({ type: "back" });
    this.emit();
  }
  cancel(): void {
    this.dispatch({ type: "cancel" });
    this.emit();
  }
  requestStop(): void {
    this.dispatch({ type: "request-stop" });
    this.emit();
  }
  requestReplace(): void {
    this.dispatch({ type: "request-replace" });
    this.emit();
  }
  requestErase(): void {
    this.dispatch({ type: "request-erase" });
    this.emit();
  }

  private async commit(
    next: TimerRecord | null,
    announce: TimerAnnouncement | null,
    remaining: number,
  ): Promise<boolean> {
    if (this.busy) return false;
    this.busy = true;
    this.emit();
    try {
      const stored = next ? await this.storage.write(next) : (await this.storage.erase(), null);
      this.anchor(stored, remaining);
      this.announcement = announce;
      this.dispatch({ type: "persisted", record: stored });
      return true;
    } catch {
      this.dispatch({ type: "persist-failed" });
      return false;
    } finally {
      this.busy = false;
      this.emit();
    }
  }

  async choosePreset(presetMs: number): Promise<boolean> {
    const cur = this.state.record;
    const now = this.clocks.wall();
    const next =
      cur && cur.status !== "finished"
        ? replaceTimer(cur, { timerId: this.makeId(), presetMs, nowWallMs: now })
        : startTimer({
            timerId: this.makeId(),
            presetMs,
            nowWallMs: now,
            presentation: cur?.presentation ?? this.defaultPresentation,
            ...(cur ? { previousRevision: cur.revision } : {}),
          });
    return this.commit(next, "start", presetMs);
  }

  async pause(): Promise<boolean> {
    const cur = this.state.record;
    if (!cur || cur.status !== "running") return false;
    const r = this.tickRemaining();
    if (r <= 0) return false;
    return this.commit(pauseTimer(cur, r), "pause", r);
  }

  async resume(): Promise<boolean> {
    const cur = this.state.record;
    if (!cur || cur.status !== "paused") return false;
    return this.commit(resumeTimer(cur, this.clocks.wall()), "resume", cur.remainingMs);
  }

  async confirmStop(): Promise<boolean> {
    this.cue.stop();
    return this.commit(null, null, 0);
  }

  async acknowledge(): Promise<boolean> {
    this.cue.stop();
    const cur = this.state.record;
    if (!cur || cur.status !== "finished") return false;
    return this.commit(acknowledgeTimer(cur), null, 0);
  }

  async confirmErase(): Promise<boolean> {
    if (this.busy) return false;
    this.busy = true;
    this.emit();
    try {
      await this.storage.erase();
      this.anchor(null, 0);
      this.dispatch({ type: "persisted", record: null });
      this.state = { ...this.state, open: true, view: "pick" };
      return true;
    } catch {
      this.dispatch({ type: "persist-failed" });
      return false;
    } finally {
      this.busy = false;
      this.emit();
    }
  }

  async togglePresentation(): Promise<boolean> {
    const cur = this.state.record;
    if (!cur || cur.status === "finished") return false;
    const next: TimerPresentation = cur.presentation === "racer" ? "numerals" : "racer";
    return this.commit(setPresentation(cur, next), null, this.remaining);
  }

  private tickRemaining(): number {
    if (!this.countdown) return this.remaining;
    return this.countdown.remaining(this.clocks.mono());
  }

  /** Called by the host on an interval (~250ms) and on visibility return. */
  async tick(): Promise<void> {
    const cur = this.state.record;
    if (!cur || cur.status !== "running" || !this.countdown) return;
    const prev = this.remaining;
    const r = this.tickRemaining();
    this.remaining = r;
    this.announcement = tickAnnouncement(prev, r);
    if (r <= 0) {
      await this.finishNow(cur);
      return;
    }
    this.dispatch({ type: "tick", remainingMs: r });
    this.emit();
  }

  private async finishNow(cur: TimerRecord): Promise<void> {
    const finished = finishTimer(cur, this.clocks.wall());
    let stored = finished;
    try {
      stored = await this.storage.write(finished); // persist BEFORE the cue
    } catch {
      /* show visual finish regardless */
    }
    this.anchor(stored, 0);
    this.announcement = "finish";
    this.dispatch({ type: "persisted", record: stored });
    this.state = { ...this.state, open: true, view: "finished" };
    if (!this.cueGuard.has(stored.timerId)) {
      this.cueGuard.add(stored.timerId);
      this.cue.finish(stored.timerId);
    }
    this.emit();
  }

  pageHidden(): void {
    this.cue.stop();
    this.hidden = { mono: this.clocks.mono(), wall: this.clocks.wall() };
  }

  async pageVisible(): Promise<void> {
    const h = this.hidden;
    this.hidden = null;
    if (h && this.countdown) {
      this.remaining = this.countdown.resumeFromHidden({
        hiddenMono: h.mono,
        hiddenWall: h.wall,
        nowMono: this.clocks.mono(),
        nowWall: this.clocks.wall(),
      });
    }
    await this.tick();
  }

  /** Any key while finished stops the chime (key capture: nothing leaks). */
  anyKey(): boolean {
    if (this.state.view === "finished" && this.state.open) {
      this.cue.stop();
      return false; // key still processed inside the overlay scope (OK = Done)
    }
    return false;
  }
}
