export type WelcomeHeroState = "pending" | "ready" | "fallback";

export type ImageProbe = {
  src: string;
  complete: boolean;
  naturalWidth: number;
  decoding: string;
  onload: (() => void) | null;
  onerror: (() => void) | null;
  decode?: () => Promise<void>;
};

type PreloadLink = {
  rel: string;
  as: string;
  href: string;
  imageSrcset?: string;
  imageSizes?: string;
  dataset: Record<string, string | undefined>;
};

type PreloadDocument = {
  head: { appendChild(node: unknown): void };
  createElement(tag: "link"): PreloadLink;
  querySelector(selector: string): PreloadLink | null;
};

export const WELCOME_HERO_TIMEOUT_MS = 5000;
/** PM ruling 2026-09-24: after the timeout fallback settles, keep listening
 *  for ONE late decode while Welcome stays mounted - then stop. */
export const WELCOME_HERO_LATE_SWAP_MS = 30000;
const PRELOAD_MARK = "nilaWelcomeHero";
const PRELOAD_SELECTOR = "link[data-nila-welcome-hero]";

/** Install exactly one preload whose selectors match the hero's candidates
 *  (responsive: imagesrcset/imagesizes mirror the img so the browser reuses
 *  the preload for the same candidate it will pick). */
export function ensureWelcomeHeroPreload(
  doc: PreloadDocument,
  src: string,
  imageSrcSet?: string,
  imageSizes?: string,
): void {
  const previous = doc.querySelector(PRELOAD_SELECTOR);
  if (previous?.href === src && previous?.imageSrcset === imageSrcSet) return;
  const link = doc.createElement("link");
  link.rel = "preload";
  link.as = "image";
  link.href = src;
  if (imageSrcSet) link.imageSrcset = imageSrcSet;
  if (imageSizes) link.imageSizes = imageSizes;
  link.dataset[PRELOAD_MARK] = "true";
  doc.head.appendChild(link);
}

/**
 * One probe owns readiness for every rendering of the Welcome character.
 * Terminal precedence, PM ruling 2026-09-24:
 *  - ready first: publish ready, done.
 *  - error first: publish fallback, terminal - no swap, no retry.
 *  - 5s silence: publish fallback (settled visual state) but keep listening;
 *    ONE late load/decode while still mounted crossfades the hero in, then
 *    done. Listening stops for good at 30s or on unmount.
 * decode rejection is never failure: load/error/timeout stays authoritative.
 */
export function watchWelcomeHero(
  src: string,
  image: ImageProbe,
  publish: (state: WelcomeHeroState) => void,
  setTimer: (callback: () => void, delay: number) => ReturnType<typeof setTimeout> = setTimeout,
  clearTimer: (id: ReturnType<typeof setTimeout>) => void = clearTimeout,
): () => void {
  let done = false;
  const timers = new Set<ReturnType<typeof setTimeout>>();
  const later = (callback: () => void, delay: number) => {
    const id = setTimer(() => {
      timers.delete(id);
      callback();
    }, delay);
    timers.add(id);
  };
  const detach = () => {
    image.onload = null;
    image.onerror = null;
  };
  const stop = () => {
    if (done) return;
    done = true;
    for (const id of timers) clearTimer(id);
    timers.clear();
    detach();
  };
  const finish = (state: Exclude<WelcomeHeroState, "pending">) => {
    if (done) return;
    publish(state);
    stop();
  };
  later(() => {
    if (done) return;
    publish("fallback");
  }, WELCOME_HERO_TIMEOUT_MS);
  later(stop, WELCOME_HERO_LATE_SWAP_MS);
  image.decoding = "async";
  image.onload = () => finish("ready");
  image.onerror = () => finish("fallback");
  image.src = src;

  if (image.complete) {
    // Already settled by the cache: a broken image is the terminal error
    // path; a decoded one is ready. Either way no listener survives.
    if (image.naturalWidth > 0) finish("ready");
    else finish("fallback");
  } else if (image.decode) {
    void image.decode().then(
      () => finish("ready"),
      () => {
        // A decode rejection may precede a valid load. Keep waiting.
      },
    );
  }

  return stop;
}
