/**
 * Server-driven screen model. The core renders state and owns no rules:
 * every screen arrives as a definition from the backend (or the offline
 * cache of one), and the kid loop is a reducer over those definitions.
 *
 * The v0 kid loop (user-flows-kid): face picker -> morning shelf -> card
 * detail (read-aloud) -> I-did-it / undo -> celebration -> cleared shelf ->
 * ending (expired R45 / graduated R46).
 */

import type { CelebrationConceptId } from "./celebration-draw";

export type StarSize = "quick" | "proper" | "big";

/** The quiz extension (gaming-mechanics "Pick the answer"): a question with
 * picture-or-word answers. One bit crosses back - answered or not (R6); when
 * the content declares a right answer the card may show which one it was. */
export interface QuizAnswer {
  id: string;
  label: string;
  imageUrl: string | null;
}

export interface QuizDefinition {
  prompt: string;
  answers: QuizAnswer[];
  /** Present only on content that has a right answer (declared lessons). */
  correctAnswerId: string | null;
}

export interface CardDefinition {
  id: string;
  title: string;
  /** Secondary activity text under the title (split from the corpus copy server-side). */
  description?: string;
  size: StarSize;
  /** Pre-generated server TTS clip; the TV never synthesizes speech itself. */
  audioUrl: string | null;
  /** assets/characters/<character>-<pose>.png */
  characterImage: string | null;
  /** Present when the card is a quiz: the answer is the completion. */
  quiz?: QuizDefinition | null;
  /** Present when the card is a video activity (spec v1.1 + PM amendment
   * 2026-09-24): content.media passed through from the shelf payload,
   * validated at the type boundary (readActivityMedia). Completion is the
   * 90% legit-played latch + the kid's own Done tap - never on open. */
  media?: import("../../../../packages/domain/src/video/media.ts").ActivityMedia | null;
  /** The optional bigger go printed on the card (reward-system R13/R14): an
   * extra ask on the same rationed card, worth one extra star. Null when the
   * card offers none. */
  stepUp?: { ask: string; result: string } | null;
  boosted: boolean;
  done: boolean;
  /** n-goes progress (reward-system R9): marks this kid has made on this card today. */
  goesDone?: number;
  goesRequired?: number;
  /** What a finished card pays before boost/step-up - R13: the card says what it pays. */
  baseStars?: number;
  /** alone | someone | grown-up - R13: who needs to be there. */
  requires?: string;
  /** F8: resolved adult-role render field. v2 rows map from the audience
   * column (child_solo -> alone; siblings -> someone; child_plus_parent /
   * parent_leads_child / whole_family -> grown-up); legacy rows fall back to
   * requires verbatim. Resolved server-side at the type boundary. */
  adultRole?: string;
  /** F8: "about N minutes", from corpus active_minutes (v2 rows, 8-35). */
  timeMinutes?: number;
  /** F8: "what you need", from corpus needs (v2 rows); [] renders as nothing needed. */
  materials?: string[];
  /** F8 render vocabulary: corpus cleanup none/low/medium maps to
   * none/a-little/a-lot (high caps at a-lot). Corpus keeps its values. */
  messLevel?: string;
  /** F8: one checkable line the kid can verify (corpus done_when; v1 rows
   * carry doneWhen). Present on all v2 rows per corpus-curator. */
  doneWhen?: string;
  /** Corpus card id; its painted tile lives at assets/tiles/<corpusId>.jpg when one exists. */
  corpusId?: string | null;
  /** P0 semantic-art pipeline: the painted tile the matcher picked for a
   * parent-created card. Null while art-pending - the client renders NO
   * art rather than generic art (art-block gate, converged assessment). */
  artCorpusId?: string | null;
  artPending?: boolean;
}

export type ScreenDefinition =
  | {
      /** Nila intro (DS-1 mock canon welcome beat, F31 class-A build).
       * Entry routing into the live flow is a PM call - shot-mode + an
       * App-owned meet-worlds transition for now. */
      kind: "welcome";
    }
  | {
      kind: "face-picker";
      kids: {
        id: string;
        name: string;
        avatarImage: string | null;
        cutoutImage?: string | null;
      }[];
      /** Runtime pairing (2026-09-14): set when the device holds no family
       * (no build-time id, no paired key) - the picker shows the grown-up
       * "Pair this TV" entry alongside the faces. */
      pairEntry?: boolean;
      /** PICKER-fix v1.1 F8 (PM row 308): the failed-profile-load state.
       * Set only by the ?demo-empty fixture; the failure NEVER falls
       * through to the bundled Demo Kid identities. */
      loadFailed?: boolean;
    }
  | {
      /** Tenancy stage 3 (Option 1, founder-ruled 2026-09-14): a non-demo
       * kid picked with no paired family key lands here - the grown-up
       * types the household key once and the TV remembers it. */
      kind: "pairing";
      /** Empty when pairing from the picker's grown-up entry (no face
       * picked yet - runtime pairing, 2026-09-14). */
      kidId: string;
      /** Set when the server refused the stored key (rotation, typo). */
      error?: string;
    }
  | { kind: "loading-shelf"; kidId: string; attempt?: number }
  | { kind: "shelf-recovery"; kidId: string; attempt?: number }
  | {
      kind: "shelf";
      kidId: string;
      kidName: string;
      cards: CardDefinition[];
      /** Economy surfaces ride the shelf definition like everything else. */
      wallet: number;
      weekEarned: number;
      weekLine: number;
      streakRun: number;
      boostActive: boolean;
      /** Mon-Sun dots: a day fills when it holds any completion (the warm week view). */
      weekDays?: boolean[];
      /* Shot fixtures pin "today" so the gate is weekday-stable (the mock's
         stone row is fixed). Production never sets this. */
      weekTodayIndex?: number;
      /** R15: the moment's exit lands the ring on the just-completed card. */
      focusCardId?: string;
      /** Network and cache both failed; render recovery, never a fake empty shelf. */
      loadFailed?: boolean;
      /** TRIP-A: this shelf came from the offline cache - render the stale
       * marker; it is a moment old, not fresh server truth. */
      stale?: boolean;
      /** TRIP-1: a refused take-back lands here with its honest decline
       * (PM-ratified string), never silence. */
      undoDeclined?: string;
      /** Tenancy stage 3: get-shelf answered 401 - route to pairing, never
       * render this shell. */
      pairNeeded?: boolean;
    }
  | {
      kind: "store";
      kidId: string;
      wallet: number;
      items: {
        id: string;
        title: string;
        price: number;
        affordable: boolean;
        image: string;
        /** Store canon v1.0 (wave-1 Lane A): provenance label over the art
         * ("Stocked by Amma" / "The big one"); provNila paints the pink
         * "Nila unlock" variant. Optional: production rewards carry none
         * until the server grows provenance. */
        prov?: string;
        provNila?: boolean;
        /** Canon focus card: the theme focus ring (fixture-pinned for the
         * gate; production derives it from the lit next goal). */
        focus?: boolean;
        /** Canon sub-line under the price ("you have enough!"). */
        note?: string;
        /** "The big one": banner-compressed art + gold progress block. */
        big?: boolean;
        progress?: { done: number; required: number };
      }[];
      /** Beta browse (user-flows v5 decision 11): the listing read failed -
       * render recovery, never a fake empty store. */
      loadFailed?: boolean;
      /** Store cold-paint v1 (PM-ratified 2026-09-14): the locked-tap calm
       * line - "{price} stars - you have {wallet}. Keep going!", numbers
       * from the tapped tile. Absent until the first locked tap. */
      feedback?: string;
    }
  | {
      kind: "card-detail";
      kidId: string;
      card: CardDefinition;
      /** R18 mini-ack: a go advanced without finishing the card - stamp fill
       * and goes line tick in place, no overlay, no takeover. */
      miniAck?: { goesDone: number; goesRequired: number; at: number };
      /** SHOT-ONLY (D-FIXTURES, lease #6): deterministic detail-state seeding
       * for the visual-diff gate. Set only by shot fixtures; production
       * transitions never set it (locked by shot-fixtures.test.ts). */
      shotDetail?: "base" | "loading" | "commit-error";
    }
  | {
      /** Beat 9 (user-flows v3, PM decision 2): quiz cards SKIP the detail
       * beat - shelf -> quiz -> celebration. The beat carries its own
       * question, star value and answers. */
      kind: "quiz";
      kidId: string;
      /** Communal screen: the attribution names the kid the quiz is for. */
      kidName?: string;
      card: CardDefinition;
      /** Completion-pays (PM decision 8): set when a wrong pick committed -
       * the reveal shows INLINE in this beat; quiz-reveal-ack fires the
       * shared moment on the beat's close. */
      revealed?: boolean;
      /** TRIP-6: set after a replay from the reveal - answers are pure play
       * (re-reveal inline, no celebration, no re-commit; the star is already
       * paid, R19). */
      replayed?: boolean;
      /** I-0042: the pick committed, verdict pending - re-picks are no-ops. */
      answered?: boolean;
      /** I-0042: the verdict's answer key, stashed for the reveal and its
       * replay - the shelf payload never ships it. */
      knownCorrectAnswerId?: string | null;
      /** Shot-only state selector (RES-146 quiz wave): loading /
       * commit-error / wrong / pic render only from shot fixtures;
       * production transitions never set it (locked in
       * shot-fixtures.test.ts). */
      shotQuiz?: "base" | "loading" | "commit-error" | "wrong" | "pic";
      /** The server's verdict, stashed while the kid is on the reveal: the
       * moment's real stars and drawn concept ride into the celebration. */
      pendingMoment?: {
        kidName?: string;
        starsEarned: number;
        done?: boolean;
        goesDone?: number;
        goesRequired?: number;
        concept: CelebrationConceptId | "jackpot";
        excluded: string | null;
        walletAfter: number;
        cardsLeftToday: number;
        crossedLine: boolean;
        lineRewardTitle?: string;
        pendingSync: boolean;
      };
    }
  | {
      /** The video beat (spec v1.1): picker (2-6 items) -> player -> Done at
       * the 90% legit-played latch -> celebration. Like the quiz beat it
       * SKIPS the detail stop - one less press, same completion contract. */
      kind: "video";
      kidId: string;
      kidName?: string;
      card: CardDefinition;
      /** Shot-only state selector (video gate): picker / playing / completed /
       * autoplay-blocked / error / offline render only from shot fixtures;
       * production transitions never set it. */
      shotVideo?: "picker" | "playing" | "completed" | "autoplay-blocked" | "error" | "offline";
    }
  | { kind: "completed-card"; kidId: string; card: CardDefinition }
  | {
      kind: "celebration";
      kidId: string;
      kidName?: string;
      card: CardDefinition;
      starsEarned: number;
      /** R20 fires on every mark; done=false means more goes remain on an n-goes card. */
      done?: boolean;
      goesDone?: number;
      goesRequired?: number;
      /** r4 R11: drawn once when the completion lands, stored on this screen
       * (the completion's render record) - a re-render never re-draws. */
      concept?: CelebrationConceptId | "jackpot";
      /** R24 draw context: the last-concept exclusion applied at draw time. */
      excluded?: string | null;
      /** r4 R15 close data, computed when the completion lands. */
      walletAfter?: number;
      cardsLeftToday?: number;
      /** R16: this completion crossed the weekly star line. */
      crossedLine?: boolean;
      /** Shot fixtures only (VD production-canon cells): pins the moment's
       * phase deterministically - "close" renders the settled warm close,
       * "play" holds the hero composition (animations settled, no close
       * timer). Production flows never set this. */
      shotHold?: "play" | "close";
      lineRewardTitle?: string;
      /** R11: the mark queued offline - the close shows the honest pending
       * line and the later sync never fires a second moment. */
      pendingSync?: boolean;
    }
  | { kind: "cleared-shelf"; kidId: string; kidName: string }
  | {
      // The week's close (cadence R12-R14): earned vs the line; a cleared line
      // grants one of Nila's own small unlocks - a reward, never stars (R13/R19).
      kind: "week-close";
      kidId: string;
      earned: number;
      line: number;
      cleared: boolean;
      rewardTitle: string | null;
    }
  | {
      // The month boundary (cadence R15-R18): the quest ends; everything the
      // kid holds - stars, badges, the run - crosses untouched.
      kind: "month-close";
      kidId: string;
      heldStars: number;
      questEnds: string;
    }
  | {
      kind: "ending";
      kidId: string;
      card: CardDefinition;
      ending: "expired" | "graduated";
    }
  | {
      /** Pick your world (Sprint 5): 2x2 living previews, reversible. Client-local
            screen - the choice is device-local until the server record lands. */
      kind: "worldpick";
      kidId: string;
      kidName?: string;
      current: import("./theme").ThemeId;
      /** Set after a pick this visit - the calm line names the new world. */
      pickedName?: string;
      /** DS-1 port (shot-only): render the locked Firefly Woods 5th tile.
          Production never sets this - only the worldpick-5 shot fixture. */
      forestLocked?: boolean;
    };

export type KidEvent =
  | { type: "picked-face"; kidId: string }
  | { type: "opened-card"; cardId: string }
  | { type: "i-did-it"; cardId: string; stepUp?: boolean }
  | { type: "quiz-answered"; cardId: string; answerId: string }
  | { type: "quiz-reveal-ack" } // Completion-pays: the reveal is acknowledged, the moment fires
  | { type: "quiz-replay" } // TRIP-6: optional replay from the reveal - pure play, never a re-commit
  | { type: "undo"; cardId: string }
  | { type: "opened-store" }
  | { type: "store-locked-tap"; price: number } // Store cold-paint v1: a locked tile answers its tap (calm line)
  | { type: "open-worlds" } // Sprint 5: shelf door to the world picker
  | { type: "picked-world"; theme: import("./theme").ThemeId }
  | { type: "switch-kid" } // Two siblings, one TV: back to the face picker
  | { type: "meet-worlds" } // welcome beat: single primary door into the face picker
  | { type: "open-pairing" } // Grown-up pair entry on an unpaired picker (runtime pairing)
  | { type: "retry-shelf" }
  | { type: "retry-kids-load" } // PICKER-fix v1.1 F8: picker failure-state retry re-runs the profile load (App-owned)
  | { type: "leave"; focusCardId?: string } // Back = silent leave, no ceremony
  | { type: "pair-key-submit"; key: string }; // Pairing screen: the grown-up's key, 8 chars entered

/** Pure transition over the loop, for tests and for the offline shell. */
export function nextScreen(
  current: ScreenDefinition,
  event: KidEvent,
  shelf: (kidId: string) => Extract<ScreenDefinition, { kind: "shelf" }>,
): ScreenDefinition {
  if (event.type === "leave") {
    // Silent leave: back to wherever the kid's shelf is, never a scolding screen.
    const kidId = "kidId" in current ? current.kidId : null;
    if (!kidId) return current;
    const target = shelf(kidId);
    return event.focusCardId ? { ...target, focusCardId: event.focusCardId } : target;
  }
  switch (current.kind) {
    case "welcome":
      // App owns the transition (it holds the kids list and the key store).
      return current;
    case "face-picker":
      return event.type === "picked-face" ? { kind: "loading-shelf", kidId: event.kidId } : current;
    case "pairing":
      // App owns the transitions (it holds the kids list and the key store).
      return current;
    case "shelf-recovery":
      // F5: the retry bumps attempt so the shelf effect (keyed on it)
      // actually re-fetches instead of looping back to muddled.
      return event.type === "retry-shelf"
        ? { kind: "loading-shelf", kidId: current.kidId, attempt: (current.attempt ?? 0) + 1 }
        : current;
    case "shelf": {
      if (event.type !== "opened-card") return current;
      const card = current.cards.find((c) => c.id === event.cardId);
      if (!card) return current;
      if (card.done) return { kind: "completed-card", kidId: current.kidId, card };
      // PM decision 2: OK on a quiz card opens beat 9 directly - a detail
      // stop adds a press and no information.
      if (card.quiz) return { kind: "quiz", kidId: current.kidId, kidName: current.kidName, card };
      // Video activities open their own beat; the detail stop adds a press
      // and no information for a card whose completion is the watch itself.
      if (card.media)
        return { kind: "video", kidId: current.kidId, kidName: current.kidName, card };
      return { kind: "card-detail", kidId: current.kidId, card };
    }
    case "card-detail": {
      if (event.type === "i-did-it" && event.cardId === current.card.id) {
        // R18: a go that advances a multi-go card without finishing it gets
        // the mini-ack in place, never the overlay. The go that finishes the
        // card plays the full moment from beat 0.
        const goesRequired = current.card.goesRequired ?? 1;
        const goesDone = current.card.goesDone ?? 0;
        if (goesRequired > 1 && goesDone + 1 < goesRequired) {
          return {
            kind: "card-detail",
            kidId: current.kidId,
            card: { ...current.card, goesDone: goesDone + 1 },
            miniAck: { goesDone: goesDone + 1, goesRequired, at: Date.now() },
          };
        }
        return { kind: "celebration", kidId: current.kidId, card: current.card, starsEarned: 0 };
      }
      return current;
    }
    case "video": {
      // The Done control renders enabled only from the 90% legit-played
      // latch (C7/O3), so i-did-it here is always threshold-backed. The
      // completion path is the card-detail one, unchanged (C6).
      if (event.type === "i-did-it" && event.cardId === current.card.id) {
        return { kind: "celebration", kidId: current.kidId, card: current.card, starsEarned: 0 };
      }
      return current;
    }
    case "store": {
      if (event.type === "store-locked-tap") {
        // Store cold-paint v1 (PM-ratified 2026-09-14): the locked tile
        // answers with the calm line - numbers from the tapped tile.
        return {
          ...current,
          feedback: `${event.price} stars - you have ${current.wallet}. Keep going!`,
        };
      }
      return current;
    }
    case "quiz": {
      if (event.type === "quiz-replay") {
        // TRIP-6: replay is offered from the reveal only.
        if (!current.revealed) return current;
        return { ...current, revealed: false, replayed: true };
      }
      if (event.type === "quiz-answered" && event.cardId === current.card.id) {
        // TRIP-6: replay answers are pure play - the reveal shows again for
        // any pick; no celebration, no re-commit, no second payment.
        if (current.replayed) {
          if (current.revealed) return current;
          return { ...current, revealed: true };
        }
        // P3: one commit per quiz - a second pick after the commit is a no-op.
        if (current.revealed || current.answered) return current;
        // I-0042: the shelf payload no longer ships the answer key, so the
        // beat cannot call right/wrong itself - the pick commits (answered)
        // and the server's verdict closes the beat: wrong reveals inline,
        // anything else celebrates (PM decision 8 unchanged).
        return { ...current, answered: true };
      }
      if (event.type === "quiz-reveal-ack" && current.revealed) {
        // The shared celebration moment fires on the quiz beat's CLOSE,
        // after the reveal - one celebration, same win contract. The
        // stashed verdict (real stars, drawn concept) comes along when the
        // server has already spoken; without it the moment renders its
        // pending state exactly like a slow-network i-did-it.
        return {
          kind: "celebration",
          kidId: current.kidId,
          card: current.card,
          starsEarned: current.pendingMoment?.starsEarned ?? 0,
          ...(current.pendingMoment ?? {}),
        };
      }
      return current;
    }
    default:
      return current;
  }
}

/** The small-unlock Nila hands over itself when the week line is crossed (reward-system R19). */
export const WEEK_CLEAR_REWARD = "A new sticker for your shelf";

export function weekCloseFor(
  shelf: Extract<ScreenDefinition, { kind: "shelf" }>,
): Extract<ScreenDefinition, { kind: "week-close" }> {
  const cleared = shelf.weekEarned >= shelf.weekLine;
  return {
    kind: "week-close",
    kidId: shelf.kidId,
    earned: shelf.weekEarned,
    line: shelf.weekLine,
    cleared,
    rewardTitle: cleared ? WEEK_CLEAR_REWARD : null,
  };
}

export function monthCloseFor(
  shelf: Extract<ScreenDefinition, { kind: "shelf" }>,
  questEnds: string,
): Extract<ScreenDefinition, { kind: "month-close" }> {
  return { kind: "month-close", kidId: shelf.kidId, heldStars: shelf.wallet, questEnds };
}

/** Store cold-paint v1: the lit next goal is the cheapest LOCKED tile
 * (min price among tiles with price > wallet); none when all are affordable. */
export function storeNextGoalId(
  items: { id: string; price: number; affordable: boolean }[],
): string | null {
  const locked = items.filter((item) => !item.affordable);
  if (!locked.length) return null;
  return locked.reduce((a, b) => (a.price <= b.price ? a : b)).id;
}
